-- Inserir todos os equipamentos
INSERT INTO public.equipamentos (
  numero, nome, descricao, tipo, bonus, dano_base, elemento,
  requisitos, raridade, origem_lore, vinculo,
  categoria, propriedades, cargas, usos_por_dia
) VALUES
  (1, 'Espada Longa +1 / +2 / +3', 'Concede bônus de +1, +2 ou +3 em jogadas de ataque e dano. Considerada mágica para fins de superar resistências.', ARRAY['espada longa']::text[], '{"ataque":1,"dano":1}', NULL, ARRAY[]::text[], NULL, 'Incomum / Raro / Muito Raro', 'A versão mais básica de encantamento marcial, usada por cavaleiros, paladinos e guerreiros em todo o multiverso. Forjada por ferreiros arcanos que imbuem aço com fragmentos de magia elementar.', NULL, 'Espadas e Laminas', ARRAY['resistencia']::text[], NULL, NULL),
  (2, 'Vorpal Sword (Espada Vorpal)', 'Bônus de +3 em ataque e dano. Ao rolar 20 natural contra criatura com pescoço, decapita instantaneamente (sem direito a salvaguarda). Ignora resistências e imunidades a dano cortante.', ARRAY['espada longa', 'larga ou grande']::text[], '{"ataque":3,"dano":3}', NULL, ARRAY[]::text[], NULL, 'Lendário', 'Inspirada no poema ''Jabberwocky'' de Lewis Carroll. No multiverso, essas lâminas são forjadas com o metal das estrelas caídas e temperadas no fio do Plano Astral.', '{"requer":true,"descricao":"Bônus de +3 em ataque e dano. Ao rolar 20 natural contra criatura com pescoço, decapita instantaneamente (sem direito a salvaguarda)"}', 'Espadas e Laminas', ARRAY['imunidade', 'resistencia', 'salvaguarda']::text[], NULL, NULL),
  (3, 'Nightmaw (Navalha Negra)', '+3 em ataque/dano. Absorve a alma da vítima morta (ganha pontos de vida temporários). Concede velocidade extra. Imune a efeitos de charme e medo. Pode lançar Velocidade (Haste) 1/dia.', ARRAY['espada longa']::text[], '{"ataque":3,"dano":3}', NULL, ARRAY[]::text[], '{"classe":["guerreiro","ladino","bárbaro"]}', 'Lendário', 'Espada senciente de alinhamento caótico neutro. Criada por uma entidade além da compreensão mortal, anseia devorar almas. Seu cabo negro brilha com estrelas internas.', '{"requer":true,"restricao_tipo":"classe","restricao":["guerreiro","ladino","barbaro"],"descricao":"+3 em ataque/dano. Absorve a alma da vítima morta (ganha pontos de vida temporários)"}', 'Espadas e Laminas', ARRAY['usos_diarios', 'imunidade']::text[], NULL, 1),
  (4, 'Tidecaller (Chamadora das Marés)', '+3 em ataque/dano. Lança Respirar na Água (Water Breathing) à vontade. Concede visão no escuro subaquática. Pode lançar Controlar Água (Control Water) e Convocar Elemental d''Água 1/dia cada.', ARRAY['tridente']::text[], '{"ataque":3,"dano":3}', NULL, ARRAY[]::text[], NULL, 'Lendário', 'Tridente senciente criado por servos de um deus do mar primordial. Feito de metal aquático brilhante, emite som de ondas mesmo em terra seca.', '{"requer":true,"restricao_tipo":"especial","restricao":["Prefere adoradores do mar"],"descricao":"+3 em ataque/dano. Lança Respirar na Água (Water Breathing) à vontade"}', 'Espadas e Laminas', ARRAY['usos_diarios', 'a_vontade', 'visao_noturna', 'invocacao']::text[], NULL, 1),
  (5, 'Grudgehammer (Esmagadora)', '+3 em ataque/dano. Retorna à mão após ser arremessado. Concede sentido de tremor 60ft. Pode lançar Detectar o Bem e o Mal e Detectar Magia à vontade. Amedronta portador com claustrofobia.', ARRAY['martelo de guerra']::text[], '{"ataque":3,"dano":3}', NULL, ARRAY[]::text[], '{"raca":["anão"]}', 'Lendário', 'Forjado por anões das Montanhas Cinzentas em épocas antigas, imbecil de ódio por gigantes e goblins. Tem ciúmes doentio e prefere ficares sozinho.', '{"requer":true,"restricao_tipo":"raca","restricao":["anao"],"descricao":"+3 em ataque/dano. Retorna à mão após ser arremessado"}', 'Espadas e Laminas', ARRAY['a_vontade', 'retorno', 'arremessavel']::text[], NULL, NULL),
  (6, 'Frost Brand (Marca de Gelo)', '+1 em ataque/dano. Dano de fogo extra +1d6 (dano de frio). Apaga chamas não mágicas próximas. 1/hora pode extinguir chamas mágicas em área.', ARRAY['espada longa']::text[], '{"ataque":1,"dano":1}', '1d6', ARRAY['fogo', 'gelo']::text[], NULL, 'Muito Raro', 'Forjada nas tundras eternas do Plano Elemental do Ar, a lâmina mantém-se permanentemente fria ao toque e emite fumaça branca no calor.', '{"requer":true,"descricao":"+1 em ataque/dano. Dano de fogo extra +1d6 (dano de frio)"}', 'Espadas e Laminas', ARRAY[]::text[], NULL, NULL),
  (7, 'Sun Blade (Lâmina do Sol)', '+2 em ataque/dano. Emite luz solar (30ft brilhante, 30ft fraca). Mortos-vivos sofrem dano adicional +1d8. Conta como espada longa mas usa Destreza ou Força.', ARRAY['espada longa', 'sabre de luz']::text[], '{"ataque":2,"dano":2}', '1d8', ARRAY['radiante', 'forca']::text[], NULL, 'Raro', 'Forjada por sacerdotes de Solarion (ou divindades solares equivalentes), a lâmina é literalmente feita de luz solar condensada. Ao ativar, emite clarão dourado.', '{"requer":true,"descricao":"+2 em ataque/dano. Emite luz solar (30ft brilhante, 30ft fraca)"}', 'Espadas e Laminas', ARRAY['luminoso']::text[], NULL, NULL),
  (8, 'Flame Tongue (Língua de Fogo)', 'Sem bônus base. Ao ativar: dano adicional 2d6 de fogo. Ilumina como tocha (20ft). Pode ser desativada com comando.', ARRAY['espada longa', 'curta', 'larga ou grande']::text[], NULL, '2d6', ARRAY['fogo']::text[], NULL, 'Raro', 'Lâminas de aço especial imbuídas com elementais de fogo aprisionados. Ao pronunciar a palavra de comando, a lâmina se envolve em chamas que não queimam o portador.', '{"requer":true,"descricao":"Sem bônus base. Ao ativar: dano adicional 2d6 de fogo"}', 'Espadas e Laminas', ARRAY['luminoso']::text[], NULL, NULL),
  (9, 'Dragon Slayer (Mata-Dragão)', '+1 em ataque/dano. Contra dragões: dano adicional +3d6. Versão Giant Slayer funciona contra gigantes.', ARRAY['espada longa', 'curta ou grande']::text[], '{"ataque":1,"dano":1}', '3d6', ARRAY[]::text[], NULL, 'Raro', 'Forjadas por lendários caçadores de dragões, estas lâminas foram temperadas no sangue do primeiro dragão abatido por seu criador. Gravuras de escamas adornam o cabo.', NULL, 'Espadas e Laminas', ARRAY[]::text[], NULL, NULL),
  (10, 'Luck Blade (Lâmina da Sorte)', '+1 em ataque/dano. 1/dia: relança qualquer d20. Contém até 3 cargas de Wish (cada uso remove uma carga). Ao gastar a última, perde o poder de Wish mas mantém +1.', ARRAY['espada curta', 'longa ou larga']::text[], '{"ataque":1,"dano":1}', NULL, ARRAY[]::text[], NULL, 'Lendário', 'Lendárias entre jogadores e aventureiros. Contém 1d4-1 cargas de Desejo (Wish) aprisionadas na pedra preciosa no cabo. Considerada o item mais cobiçado no mundo.', '{"requer":true,"descricao":"+1 em ataque/dano. 1/dia: relança qualquer d20"}', 'Espadas e Laminas', ARRAY['cargas', 'usos_diarios']::text[], 3, 1),
  (11, 'Holy Avenger (Vingador Sagrado)', '+3 em ataque/dano. Dano adicional +2d10 radiante contra mortos-vivos e demônios. Aura de 10ft: aliados têm vantagem em salvaguardas contra magia. Lança Dispel Magic nível 5 à vontade.', ARRAY['espada longa']::text[], '{"ataque":3,"dano":3}', '2d10', ARRAY['radiante']::text[], '{"classe":["paladino"]}', 'Lendário', 'A espada definitiva dos paladinos. Cada Holy Avenger é forjada por um deus ou servo divino especificamente para um paladino escolhido. Brilha com luz sagrada pura.', '{"requer":true,"restricao_tipo":"classe","restricao":["paladino","ladino"],"descricao":"+3 em ataque/dano. Dano adicional +2d10 radiante contra mortos-vivos e demônios"}', 'Espadas e Laminas', ARRAY['a_vontade', 'vantagem', 'salvaguarda']::text[], NULL, NULL),
  (12, 'Nine Lives Stealer (Rouba Nove Vidas)', '+2 em ataque/dano. Contém 1d8+1 cargas. Ao rolar 20 natural contra criatura com 100 HP ou menos: deve passar em CD 15 Con ou morrer instantaneamente (usa uma carga). Sem cargas: mantém +2.', ARRAY['espada longa ou curta']::text[], '{"ataque":2,"dano":2,"ca":1}', '1d8+1', ARRAY[]::text[], NULL, 'Muito Raro', 'Criada por um necromante obsessivo com gatos. Cada alma capturada alimenta seu poder. A lâmina sussurra os nomes dos que roubou.', '{"requer":true,"descricao":"+2 em ataque/dano. Contém 1d8+1 cargas"}', 'Espadas e Laminas', ARRAY['cargas']::text[], 1, NULL),
  (13, 'Sword of Sharpness (Espada da Nitidez)', '+3 em ataque/dano. Ao rolar 20 natural: amputa um membro (dano máximo para o tipo). Ignora resistências a dano não mágico.', ARRAY['cortante: espada longa', 'larga', 'grande ou foice']::text[], '{"ataque":3,"dano":3}', NULL, ARRAY[]::text[], NULL, 'Muito Raro', 'Forjada por mestres ferreiros elfos usando técnicas perdidas de dobramento de metal e encantamento por luar. O fio nunca perde o brilho e corta pedra como manteiga.', '{"requer":true,"descricao":"+3 em ataque/dano. Ao rolar 20 natural: amputa um membro (dano máximo para o tipo)"}', 'Espadas e Laminas', ARRAY['resistencia']::text[], NULL, NULL),
  (14, 'Sword of Life Stealing (Espada Rouba-Vida)', '+2 em ataque/dano. Ao rolar 20 natural contra criatura não morta-viva: rouba 10 HP (criatura perde, portador ganha como PV temporários por 24h).', ARRAY['espada longa', 'curta ou larga']::text[], '{"ataque":2,"dano":2}', NULL, ARRAY[]::text[], NULL, 'Raro', 'Criada por vampiros e necromantes como extensão de sua sede de vida. A lâmina tem uma veia escura visível que pulsa ao drenar energia vital.', '{"requer":true,"descricao":"+2 em ataque/dano. Ao rolar 20 natural contra criatura não morta-viva: rouba 10 HP (criatura perde, portador ganha como PV temporários por 24h)"}', 'Espadas e Laminas', ARRAY[]::text[], NULL, NULL),
  (15, 'Defender (Defensora)', '+3 em ataque/dano. Pode transferir parte do bônus (1, 2 ou 3) para a CA até o próximo turno. Senciente: neutro bom.', ARRAY['espada longa', 'curta ou larga']::text[], '{"ataque":3,"dano":3}', NULL, ARRAY[]::text[], NULL, 'Lendário', 'Uma das lendárias Seven Swords of Mystery. A Defender é imbuída com o espírito de um guardião eterno — sacrifica poder ofensivo para proteger seu portador.', '{"requer":true,"descricao":"+3 em ataque/dano. Pode transferir parte do bônus (1, 2 ou 3) para a CA até o próximo turno"}', 'Espadas e Laminas', ARRAY['bonus_ca', 'senciente']::text[], NULL, NULL),
  (16, 'Scimitar of Speed (Cimitarra da Velocidade)', '+2 em ataque/dano. Como ação bônus, pode realizar um ataque adicional com a cimitarra.', ARRAY['cimitarra']::text[], '{"ataque":2,"dano":2}', NULL, ARRAY[]::text[], NULL, 'Muito Raro', 'Forjada por gênios do vento do Plano Elemental do Ar. A lâmina curva move-se tão rápido que deixa rastros dourados no ar.', '{"requer":true,"descricao":"+2 em ataque/dano. Como ação bônus, pode realizar um ataque adicional com a cimitarra"}', 'Espadas e Laminas', ARRAY[]::text[], NULL, NULL),
  (17, 'Sword of Wounding (Espada das Feridas)', '+2 em ataque/dano. Feridas causadas sangram: no início de cada turno da vítima, perde 1d4 HP (acumulável). Só pode ser curado com CD 15 Con na vez da vítima.', ARRAY['espada longa ou curta']::text[], '{"ataque":2,"dano":2}', '1d4', ARRAY[]::text[], NULL, 'Raro', 'Imbuída com venenos necróticos que impedem a cura. Feridas causadas pela lâmina são negras nas bordas e resistem à magia de cura.', '{"requer":true,"descricao":"+2 em ataque/dano. Feridas causadas sangram: no início de cada turno da vítima, perde 1d4 HP (acumulável)"}', 'Espadas e Laminas', ARRAY['cura']::text[], NULL, NULL),
  (18, 'Dawnbringer (Amanhecedor)', '+2 em ataque/dano. Lança luz solar em raio de 30ft. Dano extra +1d8 contra mortos-vivos e demônios. Fala telepaticamente com portador.', ARRAY['espada longa']::text[], '{"ataque":2,"dano":2}', '1d8', ARRAY['radiante']::text[], '{"alinhamento":["bom"]}', 'Lendário', 'Espada senciente criada pelo deus solar Amaunator. Dormiu por séculos em câmaras de um templo esquecido. Sua voz é clara e autoritária.', '{"requer":true,"restricao_tipo":"alinhamento","restricao":["bom"],"descricao":"+2 em ataque/dano. Lança luz solar em raio de 30ft"}', 'Espadas e Laminas', ARRAY['senciente', 'luminoso']::text[], NULL, NULL),
  (19, 'Vyrmadrel', '+1 em ataque/dano (não sintonizado) ou +3 (sintonizado). Inflige condição incapacitada ao acertar (CD 15 Con). Pode lançar Escuridão e Detectar Magia.', ARRAY['espada grande', 'greatsword']::text[], '{"ataque":1,"dano":1}', NULL, ARRAY[]::text[], '{"alinhamento":["não bom"]}', 'Lendário', 'Espada senciente de alinhamento neutro maligno, criada por magos do culto do dragão. Sussurra constantemente ao ouvido do portador.', '{"requer":true,"restricao_tipo":"alinhamento","restricao":["bom","não bom","não bom","qualquer não bom"],"descricao":"+1 em ataque/dano (não sintonizado) ou +3 (sintonizado). Inflige condição incapacitada ao acertar (CD 15 Con)"}', 'Espadas e Laminas', ARRAY[]::text[], NULL, NULL),
  (20, 'Moonheir (Lâmina da Lua)', '+1 a +3 em ataque/dano (por runas herdadas). Cada runa adiciona poderes únicos: imunidade a charme, dano extra, teleporte, etc. Nunca aceita humanos.', ARRAY['espada longa']::text[], '{"ataque":3,"dano":3}', NULL, ARRAY[]::text[], '{"especial":"linhagem_real"}', 'Lendário', 'Heirloom élfico passado de geração em geração dentro de linhagens nobres elfas. Cada nova geração adiciona uma runa à lâmina. Uma Moonheir com 5+ runas é aterrorizante.', '{"requer":true,"restricao_tipo":"raca","restricao":["elfo","elfos","meio-elfo"],"descricao":"+1 a +3 em ataque/dano (por runas herdadas). Cada runa adiciona poderes únicos: imunidade a charme, dano extra, teleporte, etc"}', 'Espadas e Laminas', ARRAY['imunidade', 'teleporte']::text[], NULL, NULL),
  (21, 'Oathbow (Arco do Juramento)', '+3 em ataque. Contra inimigo jurado: +3d6 dano, sem cobertura, sem desvantagem por longa distância. Desvantagem em outros ataques enquanto o jurado viver.', ARRAY['arco longo']::text[], '{"ataque":3,"dano":3}', '3d6', ARRAY[]::text[], NULL, 'Muito Raro', 'Forjado por elfos da floresta para caçadores de juramentos. Ao disparar a primeira flecha do dia, o portador deve declarar um alvo como ''inimigo jurado''.', '{"requer":true,"descricao":"+3 em ataque. Contra inimigo jurado: +3d6 dano, sem cobertura, sem desvantagem por longa distância"}', 'Espadas e Laminas', ARRAY['vantagem', 'desvantagem']::text[], NULL, NULL),
  (22, 'Rapier of the Duelist', '+2 em ataque/dano. Quando atacado em duelo (1 vs 1): +2 CA adicional. 1/dia: ao aparar um ataque, pode fazer contra-ataque imediato como reação.', ARRAY['rapieira']::text[], '{"ataque":2,"dano":2,"ca":2}', NULL, ARRAY[]::text[], NULL, 'Raro', 'Fantasia Clássica / Homebrew comum. A arma dos duelistas lendários. Diz-se que a primeira foi forjada por um mestre espadachim que vendeu sua alma ao Diabo para nunca ser vencido.', '{"requer":true,"descricao":"+2 em ataque/dano. Quando atacado em duelo (1 vs 1): +2 CA adicional"}', 'Espadas e Laminas', ARRAY['usos_diarios', 'bonus_ca']::text[], NULL, 1),
  (23, 'Betrayer''s Dagger (Adaga do Traidor)', '+2 em ataque/dano. Ataque de backstab: +4d6 contra alvos desprevenidos. Ignora magias de proteção contra projéteis. Invisível para magias de Detecção.', ARRAY['adaga']::text[], '{"ataque":2,"dano":2}', '4d6', ARRAY[]::text[], '{"classe":["ladino","assassino"]}', 'Muito Raro', 'Fantasia Clássica. Diz-se que esta adaga foi usada no primeiro assassinato da história do mundo. Absorveu tanto sangue inocente que desenvolveu sede própria.', '{"requer":true,"restricao_tipo":"classe","restricao":["ladino","assassino"],"descricao":"+2 em ataque/dano. Ataque de backstab: +4d6 contra alvos desprevenidos"}', 'Espadas e Laminas', ARRAY[]::text[], NULL, NULL),
  (24, 'Shadowblade (Lâmina da Sombra — item)', '+1 em ataque/dano. Dano necrótico em vez de físico. Em escuridão: +2d8 adicional. Invisível para visão não mágica em áreas com pouca luz.', ARRAY['espada curta']::text[], '{"ataque":1,"dano":1}', '2d8', ARRAY['radiante', 'necrotico']::text[], NULL, 'Raro', 'Fantasia. Forjada em escuridão pura do Umbrália. A lâmina é literalmente feita de sombra solidificada e desaparece completamente na escuridão.', '{"requer":true,"descricao":"+1 em ataque/dano. Dano necrótico em vez de físico"}', 'Espadas e Laminas', ARRAY['luminoso']::text[], NULL, NULL),
  (25, 'Keen Rapier +2', '+2 em ataque/dano. Ameaça crítico em 15-20 (dobra a faixa de ameaça). Variante: bônus de intensidade +1d6 de energia ao confirmar crítico.', ARRAY['rapieira']::text[], '{"ataque":2,"dano":2}', '1d6', ARRAY[]::text[], NULL, 'Raro', 'Encantamento de nitidez dobra a chance de acerto crítico. Comum entre magos-espadas e bardos que preferem elegância à brutalidade.', NULL, 'Espadas e Laminas', ARRAY[]::text[], NULL, NULL),
  (26, 'Dagger of Venom (Adaga do Veneno)', '+1 em ataque/dano. 1/dia: ativa veneno na lâmina por 1 minuto. Próximo acerto: alvo CD 15 Con ou fica envenenado (incapacitado 1 min).', ARRAY['adaga']::text[], '{"ataque":1,"dano":1}', NULL, ARRAY['veneno']::text[], NULL, 'Raro', 'Adaga comum em assassinos de guildas das sombras. A ranhura ao longo da lâmina retém veneno que nunca seca e nunca perde potência.', NULL, 'Espadas e Laminas', ARRAY['usos_diarios']::text[], NULL, 1),
  (27, 'Sword of Answering (Espada da Resposta)', '+3 em ataque/dano. Como reação, ao ser atacado por criatura no alcance: realiza um ataque de volta imediatamente. Portador deve ter o mesmo alinhamento da espada.', ARRAY['espada longa']::text[], '{"ataque":3,"dano":3}', NULL, ARRAY[]::text[], NULL, 'Lendário', 'Existem 9 Swords of Answering, cada uma vinculada a um alinhamento diferente. Criadas para representar os 9 planos de existência e seus alinhamentos.', '{"requer":true,"restricao_tipo":"especial","restricao":["alinhamento específico de cada espada"],"descricao":"+3 em ataque/dano. Como reação, ao ser atacado por criatura no alcance: realiza um ataque de volta imediatamente"}', 'Espadas e Laminas', ARRAY[]::text[], NULL, NULL),
  (28, 'Dancing Sword (Espada Dançante)', '+3 em ataque/dano. Pode ser lançada ao ar como ação bônus: flutua e ataca por conta própria (usa sua jogada de ataque). Após 4 rodadas cai.', ARRAY['espada longa', 'curta', 'larga ou grande']::text[], '{"ataque":3,"dano":3}', NULL, ARRAY[]::text[], NULL, 'Muito Raro', 'Criadas pelos elfos do Sylvaris para guardas que precisavam de mãos livres. A espada flutua e ataca sozinha por até 4 rodadas por vez.', '{"requer":true,"descricao":"+3 em ataque/dano. Pode ser lançada ao ar como ação bônus: flutua e ataca por conta própria (usa sua jogada de ataque)"}', 'Espadas e Laminas', ARRAY[]::text[], NULL, NULL),
  (29, 'Berserker Axe (Machado Berserker)', '+1 em ataque/dano. +1 máximo de pontos de vida por nível de sintonização. Maldição: ao ser danificado, deve CD 15 Sab ou entrar em frenesi (ataca aliados mais próximos).', ARRAY['machado de batalha', 'de guerra ou grande']::text[], '{"ataque":1,"dano":1}', NULL, ARRAY[]::text[], '{"especial":"amaldicoado"}', 'Raro', 'Forjado em sangue de guerreiros frenéticos do norte, este machado instila fúria selvagem em quem empunha. Muitos portadores não conseguem largar a arma.', '{"requer":true,"restricao_tipo":"maldicao","restricao":["item amaldiçoado"],"descricao":"+1 em ataque/dano. +1 máximo de pontos de vida por nível de sintonização"}', 'Espadas e Laminas', ARRAY['amaldicoado']::text[], NULL, NULL),
  (30, 'Mace of Smiting (Maça da Destruição)', '+1 em ataque/dano (não-constructo). Contra constructos: +2 em ataque/dano e +2d6 dano extra. Ao rolar 20 natural contra constructo: instantaneamente destruído (se HP ≤ 25).', ARRAY['maça']::text[], '{"ataque":1,"dano":1}', '2d6', ARRAY[]::text[], NULL, 'Raro', 'Favorita de clérigos e paladinos em batalha. Forjada nos altares de deuses da guerra, emite um som metálico divino a cada impacto.', NULL, 'Espadas e Laminas', ARRAY[]::text[], NULL, NULL),
  (31, 'Mace of Terror (Maça do Terror)', '+2 em ataque/dano. 3 cargas (recupera 1d3/amanhecer): onda de medo em 30ft (CD 15 Sab ou fica assustado por 1 minuto, foge do portador).', ARRAY['maça']::text[], '{"ataque":2,"dano":2}', '1d3', ARRAY[]::text[], NULL, 'Raro', 'Criada por magos a serviço de um rei tirano. A maça emite um campo de medo antinatural. Soldados experientes fogem da sua presença.', '{"requer":true,"descricao":"+2 em ataque/dano. 3 cargas (recupera 1d3/amanhecer): onda de medo em 30ft (CD 15 Sab ou fica assustado por 1 minuto, foge do portador)"}', 'Espadas e Laminas', ARRAY['cargas', 'cura']::text[], 3, NULL),
  (32, 'Trident of Fish Command (Tridente do Comando dos Peixes)', '+1 em ataque/dano. 3 cargas/dia: lança Dominate Beast em bestias aquáticas (CD 15). Recupera 1d3 cargas ao amanhecer.', ARRAY['tridente']::text[], '{"ataque":1,"dano":1}', '1d3', ARRAY[]::text[], NULL, 'Incomum', 'Favorito de druidas aquáticos e mestres de portos. Criado por sacerdotes de Poseidon ou divindades equivalentes.', '{"requer":true,"descricao":"+1 em ataque/dano. 3 cargas/dia: lança Dominate Beast em bestias aquáticas (CD 15)"}', 'Espadas e Laminas', ARRAY['cargas', 'usos_diarios', 'cura']::text[], 3, NULL),
  (33, 'Spear of Backbiting (Lança Traidora)', '+2 em ataque/dano com vantagem. Maldição: quando rola 1 ou 2 no dado de ataque, o ataque é redirecionado ao portador (autoataque). Oculta a maldição.', ARRAY['lança']::text[], '{"ataque":2,"dano":2}', NULL, ARRAY[]::text[], '{"especial":"amaldicoado"}', 'Muito Raro', 'Amaldiçoada. Uma lança antiga que parece ajudar mas eventualmente vira contra o portador — traindo nos piores momentos.', '{"requer":true,"restricao_tipo":"maldicao","restricao":["item amaldiçoado"],"descricao":"+2 em ataque/dano com vantagem. Maldição: quando rola 1 ou 2 no dado de ataque, o ataque é redirecionado ao portador (autoataque)"}', 'Espadas e Laminas', ARRAY['vantagem', 'amaldicoado']::text[], NULL, NULL),
  (34, 'Sword of Vengeance (Espada da Vingança)', '+1 em ataque/dano. Maldição: portador recebe desvantagem em salvaguardas de Sabedoria. Deve atacar quem o insultar (CD 15 Sab para resistir).', ARRAY['espada longa']::text[], '{"ataque":1,"dano":1}', NULL, ARRAY[]::text[], '{"especial":"amaldicoado"}', 'Incomum', 'Amaldiçoada. Forjada com o último suspiro de um guerreiro traído. A lâmina quer vingança e manipula psicologicamente o portador para buscar conflito.', '{"requer":true,"restricao_tipo":"maldicao","restricao":["item amaldiçoado"],"descricao":"+1 em ataque/dano. Maldição: portador recebe desvantagem em salvaguardas de Sabedoria"}', 'Espadas e Laminas', ARRAY['vantagem', 'desvantagem', 'amaldicoado', 'salvaguarda']::text[], NULL, NULL),
  (35, 'Shortsword of Backstabbing', '+3 em ataques furtivos. Dano de ataque furtivo aumenta em +2d6 adicional quando condições de furtividade são cumpridas. Não faz barulho ao colidir com armadura.', ARRAY['espada curta']::text[], '{"ataque":3,"dano":3}', '2d6', ARRAY[]::text[], '{"classe":["ladino"]}', 'Raro', 'Fantasia clássica. Favorita dos ladrões das guildas. Encantada para encontrar pontos cegos e vulnerabilidades na armadura do oponente.', '{"requer":true,"restricao_tipo":"classe","restricao":["ladino"],"descricao":"+3 em ataques furtivos. Dano de ataque furtivo aumenta em +2d6 adicional quando condições de furtividade são cumpridas"}', 'Espadas e Laminas', ARRAY[]::text[], NULL, NULL),
  (36, 'Dwarven Thrower (Lançador Anão)', '+3 em ataque/dano. Pode ser arremessado (alcance 20/60). Retorna à mão imediatamente após arremesso. Contra gigantes: +2d8 dano extra quando arremessado.', ARRAY['martelo de guerra']::text[], '{"ataque":3,"dano":3}', '2d8', ARRAY[]::text[], '{"raca":["anão"]}', 'Muito Raro', 'Martelo forjado pelos anões das Montanhas Profundas especialmente para ser arremessado. Cada Dwarven Thrower é uma obra de arte gravada com runas ancestrais anãs.', '{"requer":true,"restricao_tipo":"raca","restricao":["anao"],"descricao":"+3 em ataque/dano. Pode ser arremessado (alcance 20/60)"}', 'Espadas e Laminas', ARRAY['retorno', 'arremessavel']::text[], NULL, NULL),
  (37, 'Thunderhead Hammer', '+2 em ataque/dano. Ao acertar: dano extra 2d6 trovão. 1/dia: Onda Trovejante (Thunderwave) de nível 5 centrado no impacto (CD 17 Con).', ARRAY['martelo grande']::text[], '{"ataque":2,"dano":2}', '2d6', ARRAY['trovao']::text[], NULL, 'Muito Raro', 'Fantasia Clássica / Homebrew de alta qualidade. Forjado por titãs da tempestade no coração de um furacão. O martelo troveja a cada impacto e faísca com eletricidade.', '{"requer":true,"descricao":"+2 em ataque/dano. Ao acertar: dano extra 2d6 trovão"}', 'Espadas e Laminas', ARRAY['usos_diarios']::text[], NULL, 1),
  (38, 'Sword of Kaedrin (Espada de Kaedrin)', '+3 em ataque/dano. Dano extra 2d10 cortante. Concede CA +2. Pode lançar Finger of Death e Vampire''s Bite. Odeio imortal por Vhaelor. Senciente: caótico maligno.', ARRAY['espada longa']::text[], '{"ataque":3,"dano":3,"ca":2}', '2d10', ARRAY[]::text[], '{"alinhamento":["não-bom"]}', 'Artefato', 'Kaedrin foi o lugartenente vampiro de Vhaelor. Sua espada lendária finalmente o traiu, levando-o a atacar seu mestre. A lâmina tem alma própria e ódio eterno por Vhaelor.', '{"requer":true,"restricao_tipo":"alinhamento","restricao":["bom","não-bom","qualquer não-bom"],"descricao":"+3 em ataque/dano. Dano extra 2d10 cortante"}', 'Espadas e Laminas', ARRAY['bonus_ca', 'senciente']::text[], NULL, NULL),
  (39, 'Crimson Edge', '+2 em ataque/dano. Ao causar dano: reduz CA do alvo em -1 (acumulável até -5, por 1 minuto). Concede imunidade ao medo ao portador.', ARRAY['espada longa']::text[], '{"ataque":2,"dano":2}', NULL, ARRAY[]::text[], NULL, 'Lendário', 'Fantasia genérica. A lâmina vermelha como sangue nunca foi limpa — manchas de batalhas ancestrais impregnaram o metal. Diz-se que bebe a coragem dos inimigos.', '{"requer":true,"descricao":"+2 em ataque/dano. Ao causar dano: reduz CA do alvo em -1 (acumulável até -5, por 1 minuto)"}', 'Espadas e Laminas', ARRAY['imunidade', 'bonus_ca']::text[], NULL, NULL),
  (40, 'Whispering Blade', '+2 em ataque/dano. Grava silenciosamente conversas em alcance de 60ft. Portador pode reouvir até 1 hora de gravações. Invisível para Detect Magic enquanto não usada.', ARRAY['adaga']::text[], '{"ataque":2,"dano":2}', NULL, ARRAY[]::text[], NULL, 'Raro', 'Fantasia clássica. Adaga encantada por espiões de uma corte real perdida. Absorve conversas próximas e as sussurra ao portador mais tarde.', '{"requer":true,"descricao":"+2 em ataque/dano. Grava silenciosamente conversas em alcance de 60ft"}', 'Espadas e Laminas', ARRAY[]::text[], NULL, NULL),
  (41, 'Blade of the Medusa', '+2 em ataque/dano. Ao rolar 18-20: alvo deve CD 16 Con ou ficar paralisado por 1 rodada. Ao rolar 20 natural: CD 18 ou petrificado por 1 minuto.', ARRAY['espada longa']::text[], '{"ataque":2,"dano":2}', NULL, ARRAY[]::text[], NULL, 'Muito Raro', 'Fantasia mitológica. Forjada com escamas de Medusa e temperada em seu sangue. A lâmina tem um brilho esverdeado e petrificante.', '{"requer":true,"descricao":"+2 em ataque/dano. Ao rolar 18-20: alvo deve CD 16 Con ou ficar paralisado por 1 rodada"}', 'Espadas e Laminas', ARRAY[]::text[], NULL, NULL),
  (42, 'Soulreaver', '+3 em ataque/dano. Dano necrótico adicional 3d6. Cada morte causada: portador ganha 1 carga (máx 10). 5 cargas: não envelhece. 10 cargas: não precisa dormir. Porém perde emoções gradualmente.', ARRAY['espada grande', 'greatsword']::text[], '{"ataque":3,"dano":3}', '3d6', ARRAY['necrotico']::text[], '{"especial":"amaldicoado"}', 'Artefato', 'Fantasia sombria original. Forjada com fragmentos da alma de um deus morto, esta espada negra absorve a essência vital dos que abate, tornando o portador gradualmente imortal — e menos humano.', '{"requer":true,"restricao_tipo":"maldicao","restricao":["item corrompido"],"descricao":"+3 em ataque/dano. Dano necrótico adicional 3d6"}', 'Espadas e Laminas', ARRAY['cargas']::text[], 1, NULL),
  (43, 'Blade of the Crusader', '+2 em ataque/dano. Dano extra +2d6 radiante contra demônios e diabos. 1/dia: Proteção contra o Mal (Protection from Evil) em raio de 10ft por 10 minutos.', ARRAY['espada longa']::text[], '{"ataque":2,"dano":2}', '2d6', ARRAY['radiante']::text[], '{"alinhamento":["bom"]}', 'Raro', 'Fantasia religiosa. Espada abençoada pela ordem dos cruzados contra demônios. Cada lâmina tem o nome de um paladino caído gravado no cabo.', '{"requer":true,"restricao_tipo":"alinhamento","restricao":["bom"],"descricao":"+2 em ataque/dano. Dano extra +2d6 radiante contra demônios e diabos"}', 'Espadas e Laminas', ARRAY['usos_diarios']::text[], NULL, 1),
  (44, 'Thornwhip Sword', '+1 em ataque/dano. Ao acertar: galhos espinhentos brotam em 5ft ao redor do alvo (terreno difícil, dano 1d4 espinho a quem entrar). Dano extra +1d6 contra mortos-vivos.', ARRAY['espada longa']::text[], '{"ataque":1,"dano":1}', '1d4', ARRAY[]::text[], '{"classe":["druida","clérigo"]}', 'Raro', 'Fantasia druidica. Forjada com madeira petrificada de uma Árvore Ancião e metal colhido em relâmpago. A lâmina tem veios vegetais visíveis.', '{"requer":true,"restricao_tipo":"classe","restricao":["clerigo","druida"],"descricao":"+1 em ataque/dano. Ao acertar: galhos espinhentos brotam em 5ft ao redor do alvo (terreno difícil, dano 1d4 espinho a quem entrar)"}', 'Espadas e Laminas', ARRAY[]::text[], NULL, NULL),
  (45, 'Sword of the Planes', '+1 em ataque (em qualquer plano). Cada plano concede bônus diferente: Material (+1), Outer Planes (+2 vs alinhamento oposto), Inner Planes (+1 mais resistência elemental. 1/semana: Plane Shift.', ARRAY['espada longa']::text[], '{"ataque":1,"dano":1}', NULL, ARRAY[]::text[], NULL, 'Lendário', 'Uma espada capaz de abrir portais entre planos. Forjada por um arcano misterioso que viajou todos os planos de existência.', '{"requer":true,"descricao":"+1 em ataque (em qualquer plano). Cada plano concede bônus diferente: Material (+1), Outer Planes (+2 vs alinhamento oposto), Inner Planes (+1 mais resistência elemental"}', 'Espadas e Laminas', ARRAY['resistencia', 'teleporte']::text[], NULL, NULL),
  (46, 'Avenger''s Blade', '+2 em ataque/dano padrão. O portador pode designar um ''alvo de vingança'' (1/semana). Contra esse alvo: +4 em ataque/dano e vantagem em todos os ataques.', ARRAY['espada longa']::text[], '{"ataque":2,"dano":2}', NULL, ARRAY[]::text[], NULL, 'Muito Raro', 'Fantasia clássica. Criada para um herói que perdeu tudo para um vilão específico. A lâmina ''reconhece'' o inimigo do portador e amplifica o ódio em poder.', '{"requer":true,"descricao":"+2 em ataque/dano padrão. O portador pode designar um ''alvo de vingança'' (1/semana)"}', 'Espadas e Laminas', ARRAY['vantagem']::text[], NULL, NULL),
  (47, 'Goblinbane / Elvenbane Sword', '+1 em ataque/dano geral. Contra a raça designada: +2d6 dano adicional e vantagem em ataque.', ARRAY['espada longa']::text[], '{"ataque":1,"dano":1}', '2d6', ARRAY[]::text[], NULL, 'Incomum', 'Fantasia clássica. Variantes existem para diferentes raças: goblinbane, elvenbane, dragonbane. Cada uma forjada especificamente para caçar um tipo de criatura.', NULL, 'Espadas e Laminas', ARRAY['vantagem']::text[], NULL, NULL),
  (48, 'Frost Fang', '+2 em ataque/dano. Dano extra 1d6 frio. Ao rolar 18+: alvo CD 14 Con ou velocidade reduzida à metade por 1 rodada. Portador ignora terreno difícil por gelo/neve.', ARRAY['espada curta']::text[], '{"ataque":2,"dano":2}', '1d6', ARRAY['gelo']::text[], NULL, 'Raro', 'Fantasia nórdica. Forjada com presas de um dragão branco jovem e temperada em um geyser ártico.', NULL, 'Espadas e Laminas', ARRAY[]::text[], NULL, NULL),
  (49, 'Ozrendel''s Sword (Espada de Ozrendel)', 'Cria espada de força: +7 em ataque, 3d10 dano de força, pairante na área por concentração (até 1 minuto). Usada como item: lança a magia 1/dia.', ARRAY['espada de força']::text[], '{"ataque":7,"dano":7}', '3d10', ARRAY['forca']::text[], '{"classe":["conjurador"]}', 'Muito Raro', 'Criada pelo arquimago Ozrendel de Valdrun. Conjurada como magia de 7º nível, cria uma espada de força mágica pura que obedece mentalmente.', '{"requer":true,"restricao_tipo":"classe","restricao":["conjurador"],"descricao":"Cria espada de força: +7 em ataque, 3d10 dano de força, pairante na área por concentração (até 1 minuto). Usada como item: lança a magia 1/dia"}', 'Espadas e Laminas', ARRAY['usos_diarios', 'concentracao']::text[], NULL, 1),
  (50, 'Blade of Broken Mirrors', '+1 em ataque/dano. Ao acertar: alvo CD 14 Sab ou fica com medo de sua própria imagem por 1 rodada (desvantagem em ataques). 1/dia: Espelho Imagem (Mirror Image).', ARRAY['espada curta']::text[], '{"ataque":1,"dano":1}', NULL, ARRAY[]::text[], NULL, 'Raro', 'Fantasia do Sylvaris. Espelho encantado quebrado e remodelado em lâmina por uma bruxa feérica. Reflete ilusões da mente do alvo.', '{"requer":true,"descricao":"+1 em ataque/dano. Ao acertar: alvo CD 14 Sab ou fica com medo de sua própria imagem por 1 rodada (desvantagem em ataques)"}', 'Espadas e Laminas', ARRAY['usos_diarios', 'vantagem', 'desvantagem']::text[], NULL, 1),
  (51, 'Greatsword of Demolition', '+2 em ataque/dano. Dano dobrado contra objetos e estruturas. Ao acertar no chão: onda de choque em cone de 10ft (2d6 trovão, CD 13 Con ou cai no chão).', ARRAY['espada grande']::text[], '{"ataque":2,"dano":2}', '2d6', ARRAY['trovao']::text[], NULL, 'Raro', 'Fantasia clássica. Forjada para destruir construções e fortalezas. Cada swing lança uma onda de choque menor.', NULL, 'Espadas e Laminas', ARRAY[]::text[], NULL, NULL),
  (52, 'Spiked Chain of Chaos (Corrente Espinhada do Caos)', '+2 em ataque/dano. Alcance variável (5-15ft, determina aleatoriamente). Pode iniciar agarramento à distância. 1/dia: dano de força adicional 3d6 ao acertar.', ARRAY['corrente espinhada — exótica']::text[], '{"ataque":2,"dano":2}', '3d6', ARRAY['forca']::text[], '{"alinhamento":["caótico"]}', 'Muito Raro', 'Favorita de guerreiros caóticos dos Planos Exteriores. A corrente muda de comprimento e comportamento imprevisivelmente.', '{"requer":true,"restricao_tipo":"alinhamento","restricao":["caótico"],"descricao":"+2 em ataque/dano. Alcance variável (5-15ft, determina aleatoriamente)"}', 'Espadas e Laminas', ARRAY['usos_diarios']::text[], NULL, 1),
  (53, 'Keen Falchion of Wounding', '+1 em ataque/dano. Faixa de ameaça crítica 15-20. Feridas causadas sangram (1d6/rodada até curadas). Crítico confirmado: dano adicional 1d6 hemorragia.', ARRAY['falcata', 'alfanje']::text[], '{"ataque":1,"dano":1,"ca_base":15}', '1d6', ARRAY[]::text[], NULL, 'Raro', 'Combinação de encantamentos. Favorita de bárbaros e guerreiros de regiões áridas. Curva ampla feita para golpes devastadores.', NULL, 'Espadas e Laminas', ARRAY['cura']::text[], NULL, NULL),
  (54, 'Durandal', '+5 em ataque/dano (equivalente clássico). Indestrutível por meios não divinos. Dano radiante extra 4d8. Cria campo sagrado 30ft (mortos-vivos com desvantagem). Não pode ser segurada por criaturas malignas.', ARRAY['espada longa']::text[], '{"ataque":5,"dano":5}', '4d8', ARRAY['radiante']::text[], '{"alinhamento":["lawful good"]}', 'Artefato', 'Mitologia francesa — espada de Roland, paladino de Carlos Magno. Dizia-se ser indestrutível. Continha relíquias sagradas no cabo: dente de São Pedro, cabelo de São Dionísio, etc.', '{"requer":true,"restricao_tipo":"alinhamento","restricao":["lawful"],"descricao":"+5 em ataque/dano (equivalente clássico). Indestrutível por meios não divinos"}', 'Espadas e Laminas', ARRAY['vantagem', 'desvantagem']::text[], NULL, NULL),
  (55, 'Excalibur', '+5 em ataque/dano. Concede legitimidade (criaturas leais podem não atacar). A bainha: portador não pode morrer por dano (sobrevive com 1 HP sempre). Cura 2d6 no início de cada turno do portador.', ARRAY['espada longa']::text[], '{"ataque":5,"dano":5}', '2d6', ARRAY[]::text[], '{"especial":"linhagem_real"}', 'Artefato', 'Mitologia arturiana. A espada na pedra, empunhada por Artur Pendragon. Na tradição, sua bainha tinha o poder maior: quem a carregasse nunca morreria de feridas em batalha.', NULL, 'Espadas e Laminas', ARRAY['cura']::text[], NULL, NULL),
  (56, 'Gram', '+4 em ataque/dano. Dano extra +3d10 contra dragões. Imune à corrupção dracônica e ao encantamento do ouro de dragão. Pode cortar qualquer material não divino.', ARRAY['espada longa', 'grande']::text[], '{"ataque":4,"dano":4}', '3d10', ARRAY[]::text[], NULL, 'Artefato', 'Mitologia nórdica — espada de Sigurd (Siegfried). Reforjada após ser quebrada, Gram matou o dragão Fafnir. No ciclo dos Nibelungos, é símbolo do destino heróico.', NULL, 'Espadas e Laminas', ARRAY['imunidade']::text[], NULL, NULL),
  (57, 'Joyeuse', '+4 em ataque/dano. Emite clarão cegante em batalha (inimigos dentro de 30ft: CD 16 Des ou ficam cegos por 1 rodada). Portador imune a medo.', ARRAY['espada longa']::text[], '{"ataque":4,"dano":4}', NULL, ARRAY[]::text[], '{"especial":"linhagem_real"}', 'Artefato', 'Mitologia francesa — espada de Carlos Magno. ''A alegre''. Dizia-se que brilhava mais que o sol para cegar inimigos.', NULL, 'Espadas e Laminas', ARRAY['imunidade']::text[], NULL, NULL),
  (58, 'Caliburn', '+3 em ataque/dano. Legitima o portador como líder (criaturas humanoides têm desvantagem em resistir comandos do portador). 1/semana: Geas involuntário.', ARRAY['espada longa']::text[], '{"ataque":3,"dano":3}', NULL, ARRAY[]::text[], '{"especial":"linhagem_real"}', 'Artefato', 'Precursora mística de Excalibur na tradição arturiana. Alguns textos tratam como espada diferente — retirada da pedra vs a dada pela Dama do Lago.', NULL, 'Espadas e Laminas', ARRAY['vantagem', 'desvantagem']::text[], NULL, NULL),
  (59, 'Tizona', '+3 em ataque/dano. Aura de intimidação: criaturas com Desafio ≤ portador ficam amedrontadas ao vê-la empunhada (CD 16 Sab). Não funciona contra bravos.', ARRAY['espada longa']::text[], '{"ataque":3,"dano":3}', NULL, ARRAY[]::text[], '{"alinhamento":["leal"]}', 'Artefato', 'Espada lendária de El Cid Campeador (séc. XI). Segundo a tradição, amedrontava os covardes pelo seu brilho. Hoje no Museu do Exército em Madri.', NULL, 'Espadas e Laminas', ARRAY[]::text[], NULL, NULL),
  (60, 'Mjolnir (Martelo de Thor)', '+5 em ataque/dano. Retorna sempre ao portador. Dano extra 4d6 trovão + 4d6 relâmpago. Pode ser arremessado até 120ft. Convoca tempestade (Invocar Relâmpago). Apenas quem for ''digno'' pode levantá-lo.', ARRAY['martelo de guerra', 'artefato']::text[], '{"ataque":5,"dano":5}', '4d6', ARRAY['trovao', 'relampago']::text[], '{"especial":"teste_dignidade"}', 'Artefato', 'Mitologia nórdica. Forjado pelos anões Brokkr e Sindri por aposta com Loki. O cabo ficou curto por culpa de Loki, mas o poder foi inalterado. Representa trovão, relâmpago e proteção.', '{"requer":true,"descricao":"+5 em ataque/dano. Retorna sempre ao portador"}', 'Machados, Martelos e Contundentes', ARRAY['invocacao', 'retorno', 'arremessavel']::text[], NULL, NULL),
  (61, 'Axe of the Dwarvish Lords (Machado dos Senhores Anões)', '+3 em ataque/dano. Anões a 300ft sentem sua presença. Lança Terraformar (Move Earth), Transmute Rock, Stone Shape à vontade. Falar com animais de pedra.', ARRAY['machado de guerra']::text[], '{"ataque":3,"dano":3}', NULL, ARRAY[]::text[], '{"classe":["paladino"],"raca":["anão"]}', 'Artefato', 'Forjado pelo primeiro anão para unificar os clãs. Cada rei anão legítimo deve ter carregado este machado. Perdido por séculos, agora reaparece periodicamente.', '{"requer":true,"restricao_tipo":"misto","restricao":["anão ou paladino"],"descricao":"+3 em ataque/dano. Anões a 300ft sentem sua presença"}', 'Machados, Martelos e Contundentes', ARRAY['a_vontade']::text[], NULL, NULL),
  (62, 'Greataxe of Cleaving +2', '+2 em ataque/dano. Ao matar um inimigo: pode realizar ataque extra grátis contra outro inimigo adjacente (1 vez por turno). Dano crítico: rola dano 3x em vez de 2x.', ARRAY['machado grande']::text[], '{"ataque":2,"dano":2}', NULL, ARRAY[]::text[], NULL, 'Raro', 'O encantamento de cleaving permite que o golpe continue após matar um alvo. Favorito de bárbaros que enfrentam hordas.', NULL, 'Machados, Martelos e Contundentes', ARRAY[]::text[], NULL, NULL),
  (63, 'Hammer of Thunderbolts (Martelo dos Trovões)', '+1 em ataque/dano (sem cinto e luvas). Com Cinto de Força e Luvas do Poder dos Ogros: +5 em ataque/dano, +4 STR. Ao acertar gigante: CD 17 Con ou morre. Arremesso 20/60ft, retorna.', ARRAY['maça grande']::text[], '{"ataque":1,"dano":1}', NULL, ARRAY['forca']::text[], NULL, 'Lendário', 'Uma das Seven Swords of Mystery (embora seja um martelo). Forjado por ferro meteorítico e imbuído com o poder dos planos do trovão.', NULL, 'Machados, Martelos e Contundentes', ARRAY['retorno', 'arremessavel']::text[], NULL, NULL),
  (64, 'Maul of the Titans', '+2 em ataque/dano. Requer FOR 20+ para usar sem penalidades. Derruba inimigos médios ou menores automaticamente ao acertar. Ao atingir terreno: cria cratera e sismo local.', ARRAY['maça grande']::text[], '{"ataque":2,"dano":2}', NULL, ARRAY[]::text[], '{"stats":{"FOR":20}}', 'Muito Raro', 'Fantasia clássica. Forjada para uso de titãs mas eventualmente roubada por mortais poderosos. Tão pesada que requer força titânica para manejar.', '{"requer":true,"descricao":"+2 em ataque/dano. Requer FOR 20+ para usar sem penalidades"}', 'Machados, Martelos e Contundentes', ARRAY[]::text[], NULL, NULL),
  (65, 'Vorpal Axe', 'Igual à Vorpal Sword: +3 em ataque/dano, rolar 20 natural = decapitação instantânea.', ARRAY['machado de guerra']::text[], '{"ataque":3,"dano":3}', NULL, ARRAY[]::text[], NULL, 'Lendário', 'Adaptação do encantamento Vorpal para machados. Favorito de guerreiros brutais que preferem machados a espadas.', '{"requer":true,"descricao":"Igual à Vorpal Sword: +3 em ataque/dano, rolar 20 natural = decapitação instantânea"}', 'Machados, Martelos e Contundentes', ARRAY[]::text[], NULL, NULL),
  (66, 'Bonecrusher', '+2 em ataque/dano. Ao acertar: CD 15 Con ou um osso do alvo é fraturado (desvantagem em ataques por 1 rodada). Crítico: fratura permanente até curada magicamente.', ARRAY['maça']::text[], '{"ataque":2,"dano":2}', NULL, ARRAY[]::text[], NULL, 'Raro', 'Fantasia clássica. Forjada com ossos de gigante e ferro extraído de uma mina amaldiçoada. Favorita de necromantas que também sabem lutar.', NULL, 'Machados, Martelos e Contundentes', ARRAY['vantagem', 'desvantagem', 'cura']::text[], NULL, NULL),
  (67, 'Flail of Vhazrael', '+3 em ataque/dano. Cada esfera causa dano elemental diferente (fogo, frio, ácido, relâmpago, veneno). 1/dia cada: sopro do dragão correspondente (CD 18).', ARRAY['mangual']::text[], '{"ataque":3,"dano":3}', NULL, ARRAY['fogo', 'gelo', 'relampago', 'acido', 'veneno']::text[], '{"alinhamento":["maligno"]}', 'Artefato', 'Ligada à Rainha dos Dragões Maus. Cada uma das cinco cabeças de Vhazrael é representada por uma esfera do mangual, cada uma com poder dracônico diferente.', '{"requer":true,"restricao_tipo":"alinhamento","restricao":["maligno"],"descricao":"+3 em ataque/dano. Cada esfera causa dano elemental diferente (fogo, frio, ácido, relâmpago, veneno)"}', 'Machados, Martelos e Contundentes', ARRAY['usos_diarios']::text[], NULL, 1),
  (68, 'Earthshaker', '+2 em ataque/dano. 1/dia: Terremoto (Earthquake) como magia de 8º nível. Ao acertar no chão: Tremor local (Tremor Sense 30ft por 1 min). Portador imune a terreno difícil por rocha.', ARRAY['martelo de guerra']::text[], '{"ataque":2,"dano":2}', NULL, ARRAY[]::text[], NULL, 'Muito Raro', 'Fantasia elementar. Forjado no núcleo de um elemental de terra antigo que consentiu em se sacrificar para criar a arma definitiva de defesa da terra.', '{"requer":true,"descricao":"+2 em ataque/dano. 1/dia: Terremoto (Earthquake) como magia de 8º nível"}', 'Machados, Martelos e Contundentes', ARRAY['usos_diarios', 'imunidade']::text[], NULL, 1),
  (69, 'Disruption Mace (Maça da Ruptura)', '+1 em ataque/dano. Contra mortos-vivos: +2d6 dano radiante. Rolar 20 natural contra morto-vivo: destruição instantânea (CD 15 Sab para resistir).', ARRAY['maça']::text[], '{"ataque":1,"dano":1}', '2d6', ARRAY['radiante']::text[], '{"alinhamento":["bom"]}', 'Raro', 'A arma favorita dos caçadores de mortos-vivos. Abençoada por clérigos em rituais especiais de 7 dias sob luz de lua cheia.', '{"requer":true,"restricao_tipo":"alinhamento","restricao":["bom"],"descricao":"+1 em ataque/dano. Contra mortos-vivos: +2d6 dano radiante"}', 'Machados, Martelos e Contundentes', ARRAY[]::text[], NULL, NULL),
  (70, 'Club of Hill Giant Strength', 'FOR do portador aumenta para 21 enquanto em sintonização (se já for maior, não muda). +1d4 dano adicional.', ARRAY['clava']::text[], NULL, '1d4', ARRAY[]::text[], NULL, 'Incomum', 'Fantasia. Essencialmente um tronco enfeitiçado imbuído com a força bruta de um gigante das colinas.', '{"requer":true,"descricao":"FOR do portador aumenta para 21 enquanto em sintonização (se já for maior, não muda). +1d4 dano adicional"}', 'Machados, Martelos e Contundentes', ARRAY[]::text[], NULL, NULL),
  (71, 'Morningstar of Devotion', '+2 em ataque/dano. 3/dia: ao acertar, pode expulsar (turn) criaturas malignas em 10ft (CD 15 Sab). Portador recebe +2 em salvaguardas de Sabedoria.', ARRAY['estrela da manhã']::text[], '{"ataque":2,"dano":2}', NULL, ARRAY[]::text[], '{"alinhamento":["bom"]}', 'Raro', 'Fantasia religiosa. Forjada por um monge-guerreiro que jurou defender os inocentes. Cada pico representa um dos votos sagrados.', '{"requer":true,"restricao_tipo":"alinhamento","restricao":["bom"],"descricao":"+2 em ataque/dano. 3/dia: ao acertar, pode expulsar (turn) criaturas malignas em 10ft (CD 15 Sab)"}', 'Machados, Martelos e Contundentes', ARRAY['usos_diarios', 'salvaguarda']::text[], NULL, 3),
  (72, 'Runehammer of the Ancients', '+2 em ataque/dano. 3 runas ativáveis (1/descanso longo cada): Runa do Fogo (+3d6 fogo), Runa do Gelo (paralisia), Runa da Tempestade (trovão 30ft cone).', ARRAY['martelo de guerra']::text[], '{"ataque":2,"dano":2}', '3d6', ARRAY['fogo', 'gelo', 'trovao']::text[], NULL, 'Muito Raro', 'Fantasia nórdica. Gravado com runas primordiais por escaldas guerreiros das eras antigas. Cada runa concede um poder diferente quando ativada.', '{"requer":true,"descricao":"+2 em ataque/dano. 3 runas ativáveis (1/descanso longo cada): Runa do Fogo (+3d6 fogo), Runa do Gelo (paralisia), Runa da Tempestade (trovão 30ft cone)"}', 'Machados, Martelos e Contundentes', ARRAY[]::text[], NULL, NULL),
  (73, 'Greatclub of the Ogre King', '+1 em ataque/dano. FOR tratada como 23 para propósitos de carga e arrombamento. Ao matar alvo: pode assustar criaturas próximas (CD 14 Sab). Trata-se como arma grande.', ARRAY['clava grande']::text[], '{"ataque":1,"dano":1}', NULL, ARRAY[]::text[], NULL, 'Raro', 'Fantasia clássica. Pertenceu ao último Rei Ogro da região, um gigante inteligente que foi derrotado por um grupo de heróis mas sua clava permaneceu.', NULL, 'Machados, Martelos e Contundentes', ARRAY[]::text[], NULL, NULL),
  (74, 'Chaos Hammer', '+1 em ataque/dano. Ao acertar: rola 1d6 para tipo de dano adicional (1=fogo, 2=frio, 3=relâmpago, 4=ácido, 5=trovão, 6=necrótico) — 1d8 do tipo sorteado.', ARRAY['martelo de guerra']::text[], '{"ataque":1,"dano":1}', '1d6', ARRAY['fogo', 'gelo', 'necrotico', 'trovao', 'relampago', 'acido']::text[], NULL, 'Raro', 'Fantasia caótica. Forjado nos planos do caos puro. Cada golpe libera energia aleatória imprevisível.', NULL, 'Machados, Martelos e Contundentes', ARRAY[]::text[], NULL, NULL),
  (75, 'Demolition Pick', '+1 em ataque/dano. Perfura armadura: -2 à CA do alvo após acerto (acumulável até -6). Dano dobrado contra construções e criaturas de pedra.', ARRAY['picareta de guerra']::text[], '{"ataque":1,"dano":1}', NULL, ARRAY[]::text[], NULL, 'Incomum', 'Fantasia anã. Ferramenta de mineração encantada tão poderosa que serve como arma devastadora especialmente contra pedra e armadura.', NULL, 'Machados, Martelos e Contundentes', ARRAY['bonus_ca']::text[], NULL, NULL),
  (76, 'Executioner''s Axe', '+2 em ataque/dano. 1/dia: decapitação certa se o alvo estiver incapacitado, paralisado ou imóvel. Portador: vantagem em Intimidação mas desvantagem em Persuasão.', ARRAY['machado de guerra']::text[], '{"ataque":2,"dano":2}', NULL, ARRAY[]::text[], NULL, 'Raro', 'Fantasia sombria. O machado do executor de uma cidade antiga, imbuído com as últimas palavras e medos de centenas de condenados.', '{"requer":true,"descricao":"+2 em ataque/dano. 1/dia: decapitação certa se o alvo estiver incapacitado, paralisado ou imóvel"}', 'Machados, Martelos e Contundentes', ARRAY['usos_diarios', 'vantagem', 'desvantagem']::text[], NULL, 1),
  (77, 'Stonecleaver Axe', '+1 em ataque/dano. Ignora resistência e imunidade de criaturas de pedra/terra. Corta pedra como se fosse madeira.', ARRAY['machado de batalha']::text[], '{"ataque":1,"dano":1}', NULL, ARRAY[]::text[], NULL, 'Incomum', 'Fantasia anã. Forjada especificamente para combate em minas e cavernas — o fio mágico ignora resistência de pedra e pederneira.', NULL, 'Machados, Martelos e Contundentes', ARRAY['imunidade', 'resistencia']::text[], NULL, NULL),
  (78, 'Fleshrender Flail', '+2 em ataque/dano. Ao acertar: alvo sangra (1d4/rodada). O sangue drena para o portador como PV temporários. Agarramento com as correntes (grapple à distância 10ft).', ARRAY['mangual']::text[], '{"ataque":2,"dano":2}', '1d4', ARRAY[]::text[], '{"alinhamento":["não bom"]}', 'Muito Raro', 'Fantasia sombria. Criado por um carrasco-necromante como ferramenta de tortura e execução. As correntes têm ganchos que se prendem e rasgam.', '{"requer":true,"restricao_tipo":"alinhamento","restricao":["bom","não bom","não bom"],"descricao":"+2 em ataque/dano. Ao acertar: alvo sangra (1d4/rodada)"}', 'Machados, Martelos e Contundentes', ARRAY[]::text[], NULL, NULL),
  (79, 'Maulbreaker', '+2 em ataque/dano. Ao acertar alvo com armadura: -1 na CA da armadura (acumulável). Ao acertar escudo: CD 15 For ou escudo é destruído. Vantagem em arrombar portas.', ARRAY['martelo de guerra']::text[], '{"ataque":2,"dano":2}', NULL, ARRAY[]::text[], NULL, 'Raro', 'Fantasia anã. Desenvolvido especificamente para destruir armaduras e escudos. Forjado por ferreiros que eram também demolidores de fortalezas.', NULL, 'Machados, Martelos e Contundentes', ARRAY['vantagem', 'bonus_ca']::text[], NULL, NULL),
  (80, 'Spear of Destiny (Lança do Destino / Lança de Longinus)', '+4 em ataque/dano. Portador imune à morte (sobrevive com 1 HP uma vez por dia). Dano extra 4d8 radiante contra mortos-vivos e demônios. Nenhuma profecia pode afetar o portador.', ARRAY['lança']::text[], '{"ataque":4,"dano":4}', '4d8', ARRAY['radiante']::text[], NULL, 'Artefato', 'Mitologia cristã / Ocultismo. A lança que teria ferido Jesus na crucificação. Muitos imperadores acreditavam que quem a possuía controlaria o destino do mundo.', '{"requer":true,"restricao_tipo":"especial","restricao":["qualquer alinhamento"],"descricao":"+4 em ataque/dano. Portador imune à morte (sobrevive com 1 HP uma vez por dia)"}', 'Lancas, Alabardas e Armas de Haste', ARRAY['usos_diarios', 'imunidade']::text[], NULL, NULL),
  (81, 'Gungnir (Lança de Odin)', '+5 em ataque. Nunca erra (substitui d20 por 25 no ataque). Retorna instantaneamente. Juramentos feitos sobre ela são vinculantes magicamente. Causa morte instantânea a mortais (CD 20 Con).', ARRAY['lança']::text[], '{"ataque":5,"dano":5}', NULL, ARRAY[]::text[], '{"especial":"divino"}', 'Artefato', 'Mitologia nórdica. Forjada pelos anões elfos Ívalds. Nunca erra o alvo e sempre retorna à mão de Odin. Nenhum juramento feito sobre ela pode ser quebrado.', NULL, 'Lancas, Alabardas e Armas de Haste', ARRAY['retorno']::text[], NULL, NULL),
  (82, 'Halberd of the Sentinel', '+2 em ataque/dano. Como reação: ataque de oportunidade a qualquer criatura que entre no alcance (não apenas saia). Pode parar movimento de criatura atingida (CD 15 For).', ARRAY['alabarda']::text[], '{"ataque":2,"dano":2}', NULL, ARRAY[]::text[], NULL, 'Raro', 'Fantasia. Forjada para guardiões de portões e defensores de posições. Encantada para controlar terreno e punir movimentos inimigos.', '{"requer":true,"descricao":"+2 em ataque/dano. Como reação: ataque de oportunidade a qualquer criatura que entre no alcance (não apenas saia)"}', 'Lancas, Alabardas e Armas de Haste', ARRAY[]::text[], NULL, NULL),
  (83, 'Glaive of the Last Stand', '+1 em ataque/dano padrão. Quando portador tem metade do HP: +3. Quando tem menos de 1/4: +5 e dano extra +2d8. Portador não pode ser empurrado enquanto em pé.', ARRAY['glaive']::text[], '{"ataque":1,"dano":1}', '2d8', ARRAY[]::text[], NULL, 'Muito Raro', 'Fantasia épica. Forjada para um herói que sozinho defendeu um desfiladeiro contra um exército. Quanto mais ferido o portador, mais poderosa a arma.', '{"requer":true,"descricao":"+1 em ataque/dano padrão. Quando portador tem metade do HP: +3"}', 'Lancas, Alabardas e Armas de Haste', ARRAY[]::text[], NULL, NULL),
  (84, 'Trident of Warning (Tridente de Aviso)', '+1 em ataque/dano. Portador e aliados em 30ft não podem ser surpreendidos enquanto portador não estiver incapacitado.', ARRAY['tridente']::text[], '{"ataque":1,"dano":1}', NULL, ARRAY[]::text[], NULL, 'Incomum', 'Uma das melhores armas mágicas de entrada para aventureiros aquáticos. Vibra ao sentir ameaça próxima.', '{"requer":true,"descricao":"+1 em ataque/dano. Portador e aliados em 30ft não podem ser surpreendidos enquanto portador não estiver incapacitado"}', 'Lancas, Alabardas e Armas de Haste', ARRAY[]::text[], NULL, NULL),
  (85, 'Lance of Devastation', '+2 em ataque/dano. Em carga montada: dano x4 em vez de x2. Ao acertar: alvo CD 17 For ou vai ao chão e recua 10ft. 1/dia: carga de relâmpago no impacto (+4d6 elétrico).', ARRAY['lança de cavalaria']::text[], '{"ataque":2,"dano":2}', '4d6', ARRAY['relampago']::text[], '{"classe":["paladino"]}', 'Raro', 'Fantasia medieval. Criada para cavaleiros de elite. Focada em ataque de carga montada, imbuída com energia cinética mágica.', '{"requer":true,"restricao_tipo":"classe","restricao":["paladino","ladino","cavaleiro"],"descricao":"+2 em ataque/dano. Em carga montada: dano x4 em vez de x2"}', 'Lancas, Alabardas e Armas de Haste', ARRAY['usos_diarios']::text[], NULL, 1),
  (86, 'Pike of the Legion', '+1 em ataque/dano. Por cada aliado adjacente (máx 4): +1 adicional em ataque e +1d4 em dano. Bloqueia avanço de cavalaria montada automaticamente.', ARRAY['pique']::text[], '{"ataque":1,"dano":1}', '1d4', ARRAY[]::text[], NULL, 'Incomum', 'Fantasia militar. Encantada para uso em formações militares. Trabalha melhor quando outros portadores estão próximos.', NULL, 'Lancas, Alabardas e Armas de Haste', ARRAY[]::text[], NULL, NULL),
  (87, 'Scythe of the Reaper', '+3 em ataque/dano necrótico. Ignora resistência a dano necrótico. Ao matar: alma fica aprisionada por 24h (não pode ser revivida). 1/dia: mata criatura com HP ≤ 50 instantaneamente.', ARRAY['foice de guerra']::text[], '{"ataque":3,"dano":3}', NULL, ARRAY['necrotico']::text[], '{"alinhamento":["não bom"]}', 'Muito Raro', 'Fantasia necromantica. A verdadeira foice da Morte (personificada). Encontrada por mortais corajosos — ou imprudentes — que adentraram os planos além da morte.', '{"requer":true,"restricao_tipo":"alinhamento","restricao":["bom","não bom","não bom"],"descricao":"+3 em ataque/dano necrótico. Ignora resistência a dano necrótico"}', 'Lancas, Alabardas e Armas de Haste', ARRAY['usos_diarios', 'resistencia']::text[], NULL, 1),
  (88, 'Spear of the Huntress', '+2 em ataque/dano. Ao marcar uma ''presa'' (ação bônus): +4d6 dano extra contra ela. Portador sempre sabe a direção da presa marcada até 5 milhas.', ARRAY['lança']::text[], '{"ataque":2,"dano":2}', '4d6', ARRAY[]::text[], '{"classe":["caçador","patrulheiro"]}', 'Raro', 'Fantasia mítica. Forjada pela deusa da caça para seus seguidores mais devotos. Voltada para rastreamento e caça de presas específicas.', '{"requer":true,"restricao_tipo":"classe","restricao":["patrulheiro","caçador"],"descricao":"+2 em ataque/dano. Ao marcar uma ''presa'' (ação bônus): +4d6 dano extra contra ela"}', 'Lancas, Alabardas e Armas de Haste', ARRAY[]::text[], NULL, NULL),
  (89, 'Bardiche of the Black Knight', '+2 em ataque/dano necrótico. Crítico: drenar nível de vitalidade (como Bestow Curse). Portador recebe +2 CA mas emite aura de medo em 10ft (aliados incluídos).', ARRAY['bardiche', 'arma polearm']::text[], '{"ataque":2,"dano":2,"ca":2}', NULL, ARRAY['necrotico']::text[], '{"alinhamento":["maligno"]}', 'Muito Raro', 'Fantasia sombria. Empunhada por um cavaleiro negro que serviu à Morte por séculos. A arma absorveu sua lealdade maligna.', '{"requer":true,"restricao_tipo":"alinhamento","restricao":["maligno"],"descricao":"+2 em ataque/dano necrótico. Crítico: drenar nível de vitalidade (como Bestow Curse)"}', 'Lancas, Alabardas e Armas de Haste', ARRAY['bonus_ca']::text[], NULL, NULL),
  (90, 'Javelin of Lightning (Dardo de Relâmpago)', '+1 em ataque/dano. 1/dia: ao arremessar, transforma-se em raio de relâmpago (linha de 5ft x 120ft, 4d6 relâmpago, CD 13 Des metade). Recarrega ao amanhecer.', ARRAY['dardo de arremesso']::text[], '{"ataque":1,"dano":1}', '4d6', ARRAY['relampago']::text[], NULL, 'Incomum', 'Um dos itens mágicos mais acessíveis e populares entre aventureiros. Encantado com estilhaços de relâmpago solidificados.', NULL, 'Lancas, Alabardas e Armas de Haste', ARRAY['usos_diarios', 'arremessavel']::text[], NULL, 1),
  (91, 'Voulge of the Templar', '+2 em ataque/dano. Dano extra +2d6 radiante contra mortos-vivos e aberrações. Portador: proficiente em armadura pesada enquanto em sintonização.', ARRAY['voulge', 'arma polearm']::text[], '{"ataque":2,"dano":2}', '2d6', ARRAY['radiante']::text[], '{"classe":["paladino","clérigo"]}', 'Raro', 'Fantasia religiosa / medieval. Usada pelas ordens militares de templos. Encantada para ser mais eficaz contra os inimigos juramentados da fé.', '{"requer":true,"restricao_tipo":"classe","restricao":["paladino","clerigo","ladino"],"descricao":"+2 em ataque/dano. Dano extra +2d6 radiante contra mortos-vivos e aberrações"}', 'Lancas, Alabardas e Armas de Haste', ARRAY[]::text[], NULL, NULL),
  (92, 'Partisan of the Phalanx', '+1 em ataque/dano. Em formação (aliado adjacente): +2 adicional em ataque e +2 em CA. Portador: reação para interceptar ataques contra aliado adjacente.', ARRAY['partesana']::text[], '{"ataque":1,"dano":1,"ca":2}', NULL, ARRAY[]::text[], NULL, 'Incomum', 'Fantasia histórica grega. Encantada para uso em batalhas de falange. A formação fechada multiplica o poder da arma.', NULL, 'Lancas, Alabardas e Armas de Haste', ARRAY['bonus_ca']::text[], NULL, NULL),
  (93, 'Bow of the Elf Queen', '+3 em ataque/dano. Flechas disparadas nunca erram alvos que o portador tiver visto antes (vantagem garantida). 1/dia: flecha de luz solar que causa 8d8 de dano radiante.', ARRAY['arco longo']::text[], '{"ataque":3,"dano":3}', '8d8', ARRAY['radiante']::text[], NULL, 'Lendário', 'Fantasia élfica. Presenteado pela Rainha das Altas Fadas ao seu campeão. Feito de madeira de Árvore do Mundo e cordas de cabelo de unicórnio.', '{"requer":true,"restricao_tipo":"raca","restricao":["elfo"],"descricao":"+3 em ataque/dano. Flechas disparadas nunca erram alvos que o portador tiver visto antes (vantagem garantida)"}', 'Armas de Alcance', ARRAY['usos_diarios', 'vantagem', 'luminoso']::text[], NULL, 1),
  (94, 'Crossbow of Speed', '+2 em ataque/dano. Ignora a limitação de uma besta de mão por turno (pode disparar como ação bônus sem penal). Recarga automática (não precisa de ação livre).', ARRAY['besta de mão']::text[], '{"ataque":2,"dano":2}', NULL, ARRAY[]::text[], NULL, 'Raro', 'Fantasia. Encantada com mecanismo mágico de recarga automática. Favorita de ladinos e atiradores de elite.', '{"requer":true,"descricao":"+2 em ataque/dano. Ignora a limitação de uma besta de mão por turno (pode disparar como ação bônus sem penal)"}', 'Armas de Alcance', ARRAY[]::text[], NULL, NULL),
  (95, 'Arrow of Slaying (Flecha do Abate)', '+1 em ataque. Ao acertar o tipo de criatura designado: CD 17 Con ou recebe 6d10 dano de perfuração adicional (metade com sucesso). Excelente para uma única flecha decisiva.', ARRAY['flecha']::text[], '{"ataque":1,"dano":1}', '6d10', ARRAY[]::text[], NULL, 'Muito Raro', 'Flechas especializadas para um tipo específico de criatura. Cada flecha é feita com materiais daquela criatura e encantada para ser fatal a ela.', NULL, 'Armas de Alcance', ARRAY[]::text[], NULL, NULL),
  (96, 'Longbow of the Stars', '+2 em ataque/dano. Alcance dobrado (300/1200ft). Ao disparar à noite: +1d8 dano radiante adicional. 1/dia: Flecha Estelar — conjura raio de energia de estrela (10d8 radiante).', ARRAY['arco longo']::text[], '{"ataque":2,"dano":2}', '1d8', ARRAY['radiante']::text[], NULL, 'Muito Raro', 'Fantasia astronômica. Forjado sob alinhamento de cinco estrelas específicas. As flechas traçam linhas de luz no ar.', '{"requer":true,"descricao":"+2 em ataque/dano. Alcance dobrado (300/1200ft)"}', 'Armas de Alcance', ARRAY['usos_diarios']::text[], NULL, 1),
  (97, 'Returning Boomerang of Thunder', '+1 em ataque/dano. Sempre retorna à mão imediatamente. Ao retornar: pode atingir segundo alvo em linha. 1/dia: estalo sônico ao arremessar (3d6 trovão em 15ft, CD 14 Con).', ARRAY['bumerangue — exótica']::text[], '{"ataque":1,"dano":1}', '3d6', ARRAY['trovao']::text[], NULL, 'Raro', 'Fantasia tribal / oceânica. Tradição mágica de povos insulares. O bumerangue sempre retorna e cada arremesso amplia o som.', NULL, 'Armas de Alcance', ARRAY['usos_diarios', 'retorno', 'arremessavel']::text[], NULL, 1),
  (98, 'Shortbow of Paralysis', '+1 em ataque. Flechas envenenadas: ao acertar CD 15 Con ou paralisia por 1 minuto. Alvos paralisados ficam vulneráveis a ataques (crítico automático em 5ft).', ARRAY['arco curto']::text[], '{"ataque":1,"dano":1}', NULL, ARRAY[]::text[], NULL, 'Raro', 'Fantasia. Encharcado com veneno paralisante de serpentes etéreas. Usado por caçadores de recompensas que precisam de presos vivos.', '{"requer":true,"descricao":"+1 em ataque. Flechas envenenadas: ao acertar CD 15 Con ou paralisia por 1 minuto"}', 'Armas de Alcance', ARRAY[]::text[], NULL, NULL),
  (99, 'Sling of David', '+4 em ataque. Contra criaturas de tamanho Grande ou maior: +4d8 dano extra e automaticamente derruba (CD 20 For). Portador nunca sente medo ao enfrentar inimigo maior.', ARRAY['funda']::text[], '{"ataque":4,"dano":4}', '4d8', ARRAY[]::text[], NULL, 'Artefato', 'Mitologia hebraica / fantasia religiosa. A funda do jovem Davi que abateu o gigante Golias. Encantada com fé pura.', NULL, 'Armas de Alcance', ARRAY[]::text[], NULL, NULL),
  (100, 'Sharpshooter''s Crossbow', '+2 em ataque/dano. Ignora penalidade de distância longa. Alcance aumentado em 50%. Portador pode ver detalhes em 1 milha (visão de telescópio).', ARRAY['besta pesada']::text[], '{"ataque":2,"dano":2}', NULL, ARRAY[]::text[], NULL, 'Raro', 'Fantasia militar. Criada por engenheiros mágicos para atiradores de elite militares. A lente encantada amplia a visão e corrige a trajetória.', NULL, 'Armas de Alcance', ARRAY[]::text[], NULL, NULL),
  (101, 'Phantom Arrows Quiver (Aljava das Flechas Fantasma)', 'Produz flechas mágicas ilimitadas (+1 em ataque/dano). Flechas desaparecem após acertar. Não substitui flechas especiais colocadas na aljava.', ARRAY['aljava']::text[], '{"ataque":1,"dano":1}', NULL, ARRAY[]::text[], NULL, 'Incomum', 'Fantasia. Aljava que nunca esvazia — cria flechas de energia mágica ao ser alcançada.', NULL, 'Armas de Alcance', ARRAY[]::text[], NULL, NULL),
  (102, 'Net of Binding', 'Ao prender alvo: CD 20 For para escapar (em vez de 10). Criaturas com asa não podem voar. Alvo preso recebe dano 1d6/rodada se tentar se mover. Dura 1h ou até cortada (+5 CA, imune a bludgeoning).', ARRAY['rede mágica']::text[], '{"ca":5}', '1d6', ARRAY[]::text[], NULL, 'Raro', 'Fantasia gladiatorial / mediterrânea. Rede tecida com fios de prata e encantada por magos das arenas. Impossível de romper por força mortal.', NULL, 'Armas de Alcance', ARRAY['imunidade', 'bonus_ca', 'voo']::text[], NULL, NULL),
  (103, 'Bolas of Entanglement', '+1 em ataque (arremesso 20/60ft). Ao acertar: alvo restrito (velocidade 0). CD 15 Des ou Atletismo para escapar por turno. 3 usos/dia (recarrega ao descanso longo).', ARRAY['bolas de arremesso — exótica']::text[], '{"ataque":1,"dano":1}', NULL, ARRAY[]::text[], NULL, 'Incomum', 'Fantasia nativa americana / sul-americana adaptada. Bolas encantadas que se expandem magicamente ao capturar alvo.', NULL, 'Armas de Alcance', ARRAY['usos_diarios', 'arremessavel']::text[], NULL, NULL),
  (104, 'Siege Crossbow of Destruction', '+1 em ataque. Dano 4d12 de perfuração. Penetra até 10ft de pedra sólida. Ao acertar estrutura: abre buracho transitável (5x5ft). Requer 2 rodadas para recarregar.', ARRAY['besta de cerco — pesada']::text[], '{"ataque":1,"dano":1}', '4d12', ARRAY[]::text[], '{"stats":{"FOR":18}}', 'Muito Raro', 'Fantasia de engenharia militar. Besta mágica de cerco, muito grande para uso convencional mas devastadora contra estruturas.', NULL, 'Armas de Alcance', ARRAY[]::text[], NULL, NULL),
  (105, 'Blowgun of Sleep', 'Dardo: CD 13 Con ou sono profundo por 1 hora (como Sleep mas afeta qualquer criatura). Silenciosa: não pode ser ouvida. 10 dardos/dia (recarrega ao descanso longo).', ARRAY['zarabatana']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Fantasia tropical / nativa. Encantada com sonífero perpétuo que nunca seca.', NULL, 'Armas de Alcance', ARRAY['usos_diarios']::text[], NULL, NULL),
  (106, 'Armor of Invulnerability (Armadura da Invulnerabilidade)', 'CA 18 +Des. Resistência a todos os danos não mágicos. 1/dia: imune a todos os danos não mágicos por 10 minutos.', ARRAY['placas']::text[], '{"ca_base":18}', NULL, ARRAY[]::text[], NULL, 'Lendário', 'Forjada com metal de um meteorito que sobreviveu à entrada na atmosfera sem dano. O ferreiro foi guiado por uma divindade durante a forja.', '{"requer":true,"descricao":"Resistência a todos os danos não mágicos. 1/dia: imune a todos os danos não mágicos por 10 minutos"}', 'Armaduras e Escudos', ARRAY['usos_diarios', 'imunidade', 'resistencia', 'bonus_ca']::text[], NULL, 1),
  (107, 'Demon Armor (Armadura do Demônio)', 'CA 18. Garras de demônio: ataques desarmados causam 1d8 de dano. Maldição: desvantagem em ataques contra demônios. Portador fica com Maldição de Demônio.', ARRAY['placas completas']::text[], '{"ca_base":18}', '1d8', ARRAY[]::text[], '{"especial":"amaldicoado"}', 'Muito Raro', 'Amaldiçoada. Armadura forjada no Abismo com metal de demônio. Quem a usa sente o sussurro de entidades malignas.', '{"requer":true,"restricao_tipo":"maldicao","restricao":["item amaldiçoado"],"descricao":"Garras de demônio: ataques desarmados causam 1d8 de dano. Maldição: desvantagem em ataques contra demônios"}', 'Armaduras e Escudos', ARRAY['vantagem', 'desvantagem', 'bonus_ca', 'amaldicoado']::text[], NULL, NULL),
  (108, 'Dragon Scale Mail (Cota de Malhas de Escamas de Dragão)', 'CA 14 +Des(máx 3). Resistência ao tipo elemental do dragão. Desvantagem em testes de Furtividade do dragão para detectar o portador. Tipo varia: vermelho (fogo), azul (elétrico), etc.', ARRAY['cota de escamas']::text[], '{"ca_base":14}', NULL, ARRAY['fogo', 'relampago']::text[], NULL, 'Muito Raro', 'Forjada com escamas de dragão adulto (tipo específico determina resistência elemental). Cada armadura é única para o tipo de dragão.', '{"requer":true,"descricao":"CA 14 +Des(máx 3). Resistência ao tipo elemental do dragão"}', 'Armaduras e Escudos', ARRAY['vantagem', 'desvantagem', 'resistencia', 'bonus_ca']::text[], NULL, NULL),
  (109, 'Plate Armor of Etherealness (Armadura Etérea)', 'CA 18. 1/dia: torna-se etéreo (incluindo roupas e itens carregados) por 10 minutos — pode atravessar paredes e objetos sólidos.', ARRAY['placas completas']::text[], '{"ca_base":18}', NULL, ARRAY[]::text[], NULL, 'Lendário', 'Forjada por um mago-ferreiro que passou 10 anos no Plano Etéreo. O metal tem qualidade fantasmagórica que permite ao portador desaparecer.', '{"requer":true,"descricao":"1/dia: torna-se etéreo (incluindo roupas e itens carregados) por 10 minutos — pode atravessar paredes e objetos sólidos"}', 'Armaduras e Escudos', ARRAY['usos_diarios', 'bonus_ca']::text[], NULL, 1),
  (110, 'Mithral Armor (Armadura de Mitral)', 'Qualquer armadura de metal feita em mitral: remove o check de penalidade, remove o requisito de força. Não conta como armadura pesada para Arcane Spell Failure.', ARRAY['qualquer metálica']::text[], NULL, NULL, ARRAY['forca']::text[], NULL, 'Incomum', 'Mitral é um metal aerialmente leve e resistente de lendas élficas e anãs. Permite que qualquer conjurador use armadura metálica sem penalidade.', NULL, 'Armaduras e Escudos', ARRAY[]::text[], NULL, NULL),
  (111, 'Adamantine Armor (Armadura de Adamantino)', 'Qualquer acerto crítico contra o portador se torna acerto normal (nenhum crítico funciona contra o portador enquanto vestindo).', ARRAY['média ou pesada', 'não couro']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Adamantino é o metal mais duro do mundo. Extraído de meteoritos e forjado em condições extremas de calor e pressão mágica.', NULL, 'Armaduras e Escudos', ARRAY[]::text[], NULL, NULL),
  (112, 'Animated Shield (Escudo Animado)', '+2 CA normal. Como ação bônus: o escudo flutua e protege autonomamente por 1 minuto (mantém +2 CA com as mãos livres). Recarrega após descanso curto.', ARRAY['escudo']::text[], '{"ca":2}', NULL, ARRAY[]::text[], NULL, 'Muito Raro', 'Escudo que flutua e defende independentemente. Criado por ferreiros que animaram construtos de metal em placas de escudo.', '{"requer":true,"descricao":"+2 CA normal. Como ação bônus: o escudo flutua e protege autonomamente por 1 minuto (mantém +2 CA com as mãos livres)"}', 'Armaduras e Escudos', ARRAY['bonus_ca']::text[], NULL, NULL),
  (113, 'Shield of Expression (Escudo da Expressão)', '+2 CA. O rosto no escudo pode expressar qualquer emoção (ação bônus). Essencialmente cosmético, mas útil para comunicação não verbal à distância.', ARRAY['escudo']::text[], '{"ca":2}', NULL, ARRAY[]::text[], NULL, 'Comum', 'Escudo mágico divertido cujo rosto na face pode expressar emoções controláveis.', NULL, 'Armaduras e Escudos', ARRAY['bonus_ca']::text[], NULL, NULL),
  (114, 'Shield of Missile Attraction', '+2 CA contra ataques corpo a corpo. Maldição: ataques com projéteis (arcos, bestas, feitiços de alcance) têm vantagem contra o portador. Não pode ser removido sem Remover Maldição.', ARRAY['escudo']::text[], '{"ca":2}', NULL, ARRAY[]::text[], '{"especial":"amaldicoado"}', 'Raro', 'Amaldiçoado. Aparenta ser um escudo protetivo mas na verdade atrai projéteis com força magnética.', '{"requer":true,"restricao_tipo":"maldicao","restricao":["item amaldiçoado"],"descricao":"+2 CA contra ataques corpo a corpo. Maldição: ataques com projéteis (arcos, bestas, feitiços de alcance) têm vantagem contra o portador"}', 'Armaduras e Escudos', ARRAY['vantagem', 'bonus_ca', 'amaldicoado']::text[], NULL, NULL),
  (115, 'Spellguard Shield (Escudo Guardião de Magia)', '+2 CA. Vantagem em salvaguardas contra magias e efeitos mágicos. Criaturas com magias têm desvantagem em jogadas de ataque contra o portador.', ARRAY['escudo']::text[], '{"ca":2}', NULL, ARRAY[]::text[], NULL, 'Muito Raro', 'Criado como resposta à proliferação de conjuradores em batalha. Incorpora múltiplos contra-encantamentos.', '{"requer":true,"descricao":"Vantagem em salvaguardas contra magias e efeitos mágicos. Criaturas com magias têm desvantagem em jogadas de ataque contra o portador"}', 'Armaduras e Escudos', ARRAY['vantagem', 'desvantagem', 'bonus_ca', 'salvaguarda']::text[], NULL, NULL),
  (116, 'Armor of Resistance (Armadura de Resistência)', 'CA normal do tipo de armadura. Resistência a um tipo de dano (determinado ao criar): fogo, frio, relâmpago, ácido, veneno, etc.', ARRAY['qualquer']::text[], NULL, NULL, ARRAY['fogo', 'gelo', 'relampago', 'acido', 'veneno']::text[], NULL, 'Raro', 'Armadura encantada para resistir a um tipo específico de dano. Comum em regiões com ameaças elementais prevalentes.', '{"requer":true,"descricao":"CA normal do tipo de armadura. Resistência a um tipo de dano (determinado ao criar): fogo, frio, relâmpago, ácido, veneno, etc"}', 'Armaduras e Escudos', ARRAY['resistencia', 'bonus_ca']::text[], NULL, NULL),
  (117, 'Cloak of Protection (Manto de Proteção)', '+1 CA e +1 em todas as salvaguardas.', ARRAY['manto']::text[], '{"ca":1}', NULL, ARRAY[]::text[], NULL, 'Incomum', 'Manto simples mas eficaz, criado por conjuradores de proteção. O mais básico dos mantos mágicos de defesa.', '{"requer":true,"descricao":"+1 CA e +1 em todas as salvaguardas"}', 'Armaduras e Escudos', ARRAY['bonus_ca', 'salvaguarda']::text[], NULL, NULL),
  (118, 'Robe of the Archmagi (Robe do Arquimago)', 'CA 15 +Des. +2 em CD de magias e jogadas de ataque com magias. Vantagem em salvaguardas de magias. Diferentes versões para bom, neutro e mau.', ARRAY['robe mágica']::text[], '{"ca_base":15}', NULL, ARRAY[]::text[], '{"classe":["mago","feiticeiro"]}', 'Lendário', 'A vestimenta definitiva de um conjurador de alto nível. Criada somente quando um arquimago se aproxima do fim de sua vida e passa seu poder adiante.', '{"requer":true,"restricao_tipo":"classe","restricao":["mago","feiticeiro","bruxo"],"descricao":"+2 em CD de magias e jogadas de ataque com magias. Vantagem em salvaguardas de magias"}', 'Armaduras e Escudos', ARRAY['vantagem', 'bonus_ca', 'salvaguarda']::text[], NULL, NULL),
  (119, 'Leather Armor of Shadow', 'CA 12 +Des. Vantagem em Furtividade em áreas de penumbra ou escuridão. 1/dia: invisibilidade em escuridão total por 1 hora.', ARRAY['couro']::text[], '{"ca_base":12}', NULL, ARRAY[]::text[], NULL, 'Raro', 'Fantasia. Armadura de couro impregnada com sombras do Umbrália. Permite ao portador mesclar-se às sombras.', '{"requer":true,"descricao":"Vantagem em Furtividade em áreas de penumbra ou escuridão. 1/dia: invisibilidade em escuridão total por 1 hora"}', 'Armaduras e Escudos', ARRAY['usos_diarios', 'vantagem', 'bonus_ca', 'invisibilidade']::text[], NULL, 1),
  (120, 'Breastplate of Command (Peitoral do Comando)', 'CA 14 +Des(máx 2). Aura de liderança 60ft: aliados têm vantagem em salvaguardas contra medo enquanto portador estiver consciente.', ARRAY['peitoral']::text[], '{"ca_base":14}', NULL, ARRAY[]::text[], NULL, 'Raro', 'Forjada para líderes militares. A armadura irradia autoridade que afeta aliados e inimigos.', '{"requer":true,"descricao":"CA 14 +Des(máx 2). Aura de liderança 60ft: aliados têm vantagem em salvaguardas contra medo enquanto portador estiver consciente"}', 'Armaduras e Escudos', ARRAY['vantagem', 'bonus_ca', 'salvaguarda']::text[], NULL, NULL),
  (121, 'Half Plate of Speed', 'CA 15 +Des(máx 2). Velocidade aumentada em +10ft. Sem penalidade em Furtividade (apesar de ser meia-placa).', ARRAY['meia-placa']::text[], '{"ca_base":15}', NULL, ARRAY[]::text[], NULL, 'Raro', 'Fantasia. Forjada para guerreiros que precisam de mobilidade sem sacrificar proteção. Encantada com leveza aeromágica.', '{"requer":true,"descricao":"CA 15 +Des(máx 2). Velocidade aumentada em +10ft"}', 'Armaduras e Escudos', ARRAY['bonus_ca']::text[], NULL, NULL),
  (122, 'Shield of the Veiled Exile', '+2 CA. Imune a dano de fogo. 1/dia: bola de fogo (FireBall nível 8) centrada no portador (não afeta portador). O demônio pode susurrar e tentar influenciar.', ARRAY['escudo']::text[], '{"ca":2}', NULL, ARRAY['fogo']::text[], NULL, 'Muito Raro', 'Escudo com demônio aprisionado em seu interior. Poderoso mas corruptor.', '{"requer":true,"descricao":"Imune a dano de fogo. 1/dia: bola de fogo (FireBall nível 8) centrada no portador (não afeta portador)"}', 'Armaduras e Escudos', ARRAY['usos_diarios', 'imunidade', 'bonus_ca']::text[], NULL, 1),
  (123, 'Armor of the Fallen', 'CA 18. +2 em salvaguardas. A cada ataque que causa dano ao portador, um contador avança (máx 10). Ao 10: libera onda de energia sombria (6d8 necrótico em 20ft, CD 15).', ARRAY['placas']::text[], '{"ca_base":18}', '6d8', ARRAY['necrotico']::text[], NULL, 'Muito Raro', 'Fantasia épica. Armadura de um paladino que sucumbiu à escuridão. Ainda guarda fragmentos de sua devoção original mas corrompidos.', '{"requer":true,"descricao":"+2 em salvaguardas. A cada ataque que causa dano ao portador, um contador avança (máx 10)"}', 'Armaduras e Escudos', ARRAY['bonus_ca', 'salvaguarda']::text[], NULL, NULL),
  (124, 'Elven Chain (Cota de Malhas Élfica)', 'CA 14 +Des. Pode ser usada por conjuradores (sem penalidade). Não conta como armadura para efeitos de magia élfica. Portador pode usar proficiência com espadas longas.', ARRAY['cota de malhas']::text[], '{"ca_base":14}', NULL, ARRAY[]::text[], NULL, 'Raro', 'Tecida por artesãos elfos usando fios de mitral. Tão fina que parece têxtil ao toque mas resiste a espadas como ferro.', NULL, 'Armaduras e Escudos', ARRAY['bonus_ca']::text[], NULL, NULL),
  (125, 'Obsidian Plate Armor', 'CA 20 (+2 sobre placa normal). Imune a calor/fogo não mágico. Portador: intimidação com vantagem. Pesada: -5ft de velocidade adicional.', ARRAY['placas completas']::text[], '{"ca_base":20}', NULL, ARRAY['fogo']::text[], '{"stats":{"FOR":17}}', 'Muito Raro', 'Fantasia vulcânica. Forjada em um vulcão ativo com obsidiana encantada. Impressionante e intimidadora visualmente.', '{"requer":true,"restricao_tipo":"especial","restricao":["FOR 17+"],"descricao":"CA 20 (+2 sobre placa normal). Imune a calor/fogo não mágico"}', 'Armaduras e Escudos', ARRAY['imunidade', 'vantagem', 'bonus_ca']::text[], NULL, NULL),
  (126, 'Ring of Three Wishes (Anel dos Três Desejos)', '3 cargas de Wish. Após usar todas as cargas: anel perde poder. Wish pode conceder qualquer efeito dentro dos limites do DM, mas o DM pode interpretar literalmente.', ARRAY['anel']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Lendário', 'Um dos itens mais cobiçados do multiverso. Contém 3 cargas de Wish aprisionadas por um gênio poderoso.', '{"requer":true,"descricao":"3 cargas de Wish. Após usar todas as cargas: anel perde poder"}', 'Aneis Magicos', ARRAY['cargas']::text[], 3, NULL),
  (127, 'Ring of Invisibility (Anel da Invisibilidade)', 'Tornar-se invisível como ação. Invisibilidade quebra ao atacar, conjurar magia ou fazer check ativo. Pode permanecer invisível indefinidamente ao ficar quieto.', ARRAY['anel']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Lendário', 'O clássico anel de poder das lendas. Cada anel tem uma história — a maioria pertenceu a ladrões famosos ou espiões de reis.', '{"requer":true,"descricao":"Tornar-se invisível como ação. Invisibilidade quebra ao atacar, conjurar magia ou fazer check ativo"}', 'Aneis Magicos', ARRAY['invisibilidade']::text[], NULL, NULL),
  (128, 'Ring of Spell Storing (Anel do Armazenamento de Magia)', 'Armazena magias de nível 1-5 (total até 5 níveis combinados). Qualquer um pode conjurar as magias armazenadas usando CD e ataque do conjurador original.', ARRAY['anel']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Anel que pode armazenar até 5 níveis de magias para uso posterior. Perfeito para preparar surpresas táticas.', '{"requer":true,"descricao":"Armazena magias de nível 1-5 (total até 5 níveis combinados). Qualquer um pode conjurar as magias armazenadas usando CD e ataque do conjurador original"}', 'Aneis Magicos', ARRAY[]::text[], NULL, NULL),
  (129, 'Ring of Protection (Anel de Proteção)', '+1 CA e +1 em todas as salvaguardas.', ARRAY['anel']::text[], '{"ca":1}', NULL, ARRAY[]::text[], NULL, 'Raro', 'Um dos anéis mágicos mais comuns e úteis. Simples mas eficaz como presente para um aventureiro iniciante.', '{"requer":true,"descricao":"+1 CA e +1 em todas as salvaguardas"}', 'Aneis Magicos', ARRAY['bonus_ca', 'salvaguarda']::text[], NULL, NULL),
  (130, 'Ring of Evasion (Anel de Evasão)', '3 cargas. Ao falhar em uma salvaguarda de Destreza: usa 1 carga para ter sucesso em vez disso. Recupera 1d3 cargas ao amanhecer.', ARRAY['anel']::text[], NULL, '1d3', ARRAY[]::text[], NULL, 'Raro', 'Anel encantado para aventureiros que precisam sobreviver a magias de área. Responde instintivamente ao perigo.', '{"requer":true,"descricao":"Ao falhar em uma salvaguarda de Destreza: usa 1 carga para ter sucesso em vez disso. Recupera 1d3 cargas ao amanhecer"}', 'Aneis Magicos', ARRAY['cargas', 'cura', 'salvaguarda']::text[], 3, NULL),
  (131, 'Ring of Feather Falling (Anel da Queda de Pena)', 'Quando o portador cai, a velocidade de queda é reduzida para 60ft por rodada. Não toma dano de queda e pousa de pé.', ARRAY['anel']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Anel essencial para exploradores de torres, montanhas e masmorras de múltiplos andares. Responde automaticamente à queda.', '{"requer":true,"descricao":"Quando o portador cai, a velocidade de queda é reduzida para 60ft por rodada. Não toma dano de queda e pousa de pé"}', 'Aneis Magicos', ARRAY[]::text[], NULL, NULL),
  (132, 'Ring of Free Action (Anel da Ação Livre)', 'Imune a efeitos de terreno difícil não mágico. Imune a paralisação e restrição de velocidade por magia. Sempre tem velocidade completa.', ARRAY['anel']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Anel que anula efeitos de restrição de movimento. Essencial para guerreiros que precisam manter mobilidade máxima.', '{"requer":true,"descricao":"Imune a efeitos de terreno difícil não mágico. Imune a paralisação e restrição de velocidade por magia"}', 'Aneis Magicos', ARRAY['imunidade']::text[], NULL, NULL),
  (133, 'Ring of Regeneration (Anel da Regeneração)', 'Recupera 1d6 HP a cada 10 minutos. Membros amputados regeram em 1d6+1 dias (similar a troll). Não acelera cura por descanso.', ARRAY['anel']::text[], NULL, '1d6', ARRAY[]::text[], NULL, 'Muito Raro', 'Anel de valor incalculável para aventureiros em missões longas. Recupera HP lentamente mas continuamente, como um troll.', '{"requer":true,"descricao":"Recupera 1d6 HP a cada 10 minutos. Membros amputados regeram em 1d6+1 dias (similar a troll)"}', 'Aneis Magicos', ARRAY['cura']::text[], NULL, NULL),
  (134, 'Ring of Spell Turning (Anel do Desvio de Magia)', 'Vantagem em salvaguardas contra magias que miram somente no portador. Ao rolar 20 natural na salvaguarda: reflete a magia de volta ao conjurador.', ARRAY['anel']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Lendário', 'Anel extremamente raro e cobiçado por guerreiros contra conjuradores. Reflete magias de volta ao lançador.', '{"requer":true,"descricao":"Vantagem em salvaguardas contra magias que miram somente no portador. Ao rolar 20 natural na salvaguarda: reflete a magia de volta ao conjurador"}', 'Aneis Magicos', ARRAY['vantagem', 'salvaguarda']::text[], NULL, NULL),
  (135, 'Ring of Telekinesis (Anel da Telecinese)', 'Lança Telekinesis à vontade (concentração). Move objetos de até 1000 lb ou criaturas (CD 17 STR para resistir). Pode arremessar objetos como armas (5d6 dano).', ARRAY['anel']::text[], NULL, '5d6', ARRAY[]::text[], NULL, 'Muito Raro', 'Anel dos grandes magos. Manifestação concentrada de vontade mental sobre matéria.', '{"requer":true,"descricao":"Lança Telekinesis à vontade (concentração). Move objetos de até 1000 lb ou criaturas (CD 17 STR para resistir)"}', 'Aneis Magicos', ARRAY['a_vontade', 'concentracao', 'arremessavel']::text[], NULL, NULL),
  (136, 'Ring of the Ram (Anel do Carneiro)', '3 cargas. Força de 1-3 cargas (1d10 x cargas dano de força, empurra 5ft x cargas). Brisa objetos com 3 cargas (objetos não mágicos destruídos). Recupera 1d3 ao amanhecer.', ARRAY['anel']::text[], NULL, '1d10', ARRAY['forca']::text[], NULL, 'Raro', 'Anel que conjura força de impacto de uma cabeçada de carneiro gigante. Popular entre guerreiros que querem dissuadir ataques.', '{"requer":true,"descricao":"Força de 1-3 cargas (1d10 x cargas dano de força, empurra 5ft x cargas). Brisa objetos com 3 cargas (objetos não mágicos destruídos)"}', 'Aneis Magicos', ARRAY['cargas', 'cura']::text[], 3, NULL),
  (137, 'Ring of Mind Shielding (Anel do Escudo Mental)', 'Imune a detecção de pensamentos (Detect Thoughts). Não pode ser afetado por telepatia não desejada. Portador pode esconder alinhamento e tipo de criatura.', ARRAY['anel']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Anel que bloqueia magia de leitura mental. Criado por espiões e nobres paranóicos.', '{"requer":true,"descricao":"Imune a detecção de pensamentos (Detect Thoughts). Não pode ser afetado por telepatia não desejada"}', 'Aneis Magicos', ARRAY['imunidade']::text[], NULL, NULL),
  (138, 'Ring of Shooting Stars (Anel das Estrelas Cadentes)', 'Ao ar livre à noite: 6 cargas de Shooting Stars (4d6 de fogo, CD 15 Des, área de 15ft). Luz Perpétua à vontade. Faíscas (Flash) à vontade. Recarrega ao luar.', ARRAY['anel']::text[], NULL, '4d6', ARRAY['fogo', 'radiante']::text[], NULL, 'Muito Raro', 'Anel que captura estrelas cadentes e transforma em energia mágica ofensiva. Funciona melhor ao ar livre.', '{"requer":true,"descricao":"Ao ar livre à noite: 6 cargas de Shooting Stars (4d6 de fogo, CD 15 Des, área de 15ft). Luz Perpétua à vontade"}', 'Aneis Magicos', ARRAY['cargas', 'a_vontade', 'luminoso']::text[], 6, NULL),
  (139, 'Ring of Djinni Summoning (Anel da Convocação do Djinni)', 'Convoca um Djinn (serviçal leal) 1/dia por 1 hora. O Djinn obedece até 3 ordens simples por hora. Após 1 ano de serviço: CD 20 Sab ou o djinn se torna hostil.', ARRAY['anel']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Lendário', 'Vincula um djinn específico ao anel. O djinn serve o portador mas com ressentimento, esperando ser libertado.', '{"requer":true,"descricao":"Convoca um Djinn (serviçal leal) 1/dia por 1 hora. O Djinn obedece até 3 ordens simples por hora"}', 'Aneis Magicos', ARRAY['usos_diarios', 'invocacao']::text[], NULL, 1),
  (140, 'Ring of Earth Elemental Command', 'Resistência a ácido. Lança Stone Shape, Stoneskin, Wall of Stone, Transmute Rock. Falar com elementais de terra. Vantagem em Persuasão com elementais de terra. Compreende Terrano.', ARRAY['anel']::text[], NULL, NULL, ARRAY['acido']::text[], NULL, 'Lendário', 'Um dos cinco anéis elementais de comando. Controle sobre a terra e pedra.', '{"requer":true,"descricao":"Resistência a ácido. Lança Stone Shape, Stoneskin, Wall of Stone, Transmute Rock"}', 'Aneis Magicos', ARRAY['vantagem', 'resistencia']::text[], NULL, NULL),
  (141, 'Ring of Fire Elemental Command', 'Imunidade ao fogo. Desvantagem em ataques e testes no Plano Elemental da Água. Lança Burning Hands, Fireball (nível 7), Wall of Fire. Convoca Elemental de Fogo.', ARRAY['anel']::text[], NULL, NULL, ARRAY['fogo']::text[], NULL, 'Lendário', 'Anel elemental do fogo. Imunidade ao fogo e controle sobre chamas.', '{"requer":true,"descricao":"Imunidade ao fogo. Desvantagem em ataques e testes no Plano Elemental da Água"}', 'Aneis Magicos', ARRAY['imunidade', 'vantagem', 'desvantagem', 'invocacao']::text[], NULL, NULL),
  (142, 'Ring of Water Walking (Anel de Andar sobre Água)', 'Portador pode andar sobre qualquer superfície líquida como se fosse solo sólido.', ARRAY['anel']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Anel simples e útil para qualquer aventureiro que precise cruzar rios, oceanos ou pântanos.', NULL, 'Aneis Magicos', ARRAY[]::text[], NULL, NULL),
  (143, 'Ring of X-Ray Vision (Anel da Visão de Raio-X)', 'Ação: ver através de objetos sólidos em 30ft por 1 minuto. Ver através de até 1ft de pedra, 1 polegada de metal comum, 3ft de madeira/terra. Uso excessivo: exaustão.', ARRAY['anel']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Anel que permite ver através de paredes e objetos sólidos. Popular entre espiões mas cansativo para usar em excesso.', '{"requer":true,"descricao":"Ação: ver através de objetos sólidos em 30ft por 1 minuto. Ver através de até 1ft de pedra, 1 polegada de metal comum, 3ft de madeira/terra"}', 'Aneis Magicos', ARRAY[]::text[], NULL, NULL),
  (144, 'Ring of Warmth (Anel do Calor)', 'Resistência a dano de frio. Portador e equipamentos são mantidos confortavelmente quentes (ignora efeitos de clima frio natural).', ARRAY['anel']::text[], NULL, NULL, ARRAY['gelo']::text[], NULL, 'Incomum', 'Anel útil para exploradores de regiões árticas ou montanhosas. Popular entre pesquisadores de regiões polares.', '{"requer":true,"descricao":"Resistência a dano de frio. Portador e equipamentos são mantidos confortavelmente quentes (ignora efeitos de clima frio natural)"}', 'Aneis Magicos', ARRAY['resistencia']::text[], NULL, NULL),
  (145, 'Ring of Swimming (Anel da Natação)', 'Velocidade de natação de 40ft. Proficiente em testes de Atletismo relacionados à natação.', ARRAY['anel']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Anel que concede habilidades aquáticas. Comum em cidades portuárias e aventureiros de exploração submarina.', NULL, 'Aneis Magicos', ARRAY[]::text[], NULL, NULL),
  (146, 'Ring of Sustenance (Anel do Sustento)', 'Portador não precisa comer ou beber. Apenas 2 horas de sono por noite (com a mesma qualidade de 8 horas de descanso normal).', ARRAY['anel']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Anel mágico que torna a alimentação e o sono menos necessários. Útil para exploração de masmorras de longa duração.', '{"requer":true,"restricao_tipo":"especial","restricao":["7 dias de uso para ativar"],"descricao":"Portador não precisa comer ou beber. Apenas 2 horas de sono por noite (com a mesma qualidade de 8 horas de descanso normal)"}', 'Aneis Magicos', ARRAY[]::text[], NULL, NULL),
  (147, 'Ring of Truth Telling', 'Portador detecta mentiras automáticamente (como Zone of Truth passivo em 15ft). Desvantagem (ou impossibilidade) de mentir enquanto em sintonização.', ARRAY['anel']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Fantasia. Anel da verdade — mas duplo: detecta mentiras E obriga o portador a dizer a verdade. Perigoso para mentirosos.', '{"requer":true,"descricao":"Portador detecta mentiras automáticamente (como Zone of Truth passivo em 15ft). Desvantagem (ou impossibilidade) de mentir enquanto em sintonização"}', 'Aneis Magicos', ARRAY['vantagem', 'desvantagem']::text[], NULL, NULL),
  (148, 'Ring of the Vampire', 'Visão no escuro 120ft. Ataque de mordida (1d6 + roubo de 1d6 HP). 1/dia: encantar pessoa (Charm Person CD 16). Fraqueza: desvantagem em plena luz solar.', ARRAY['anel']::text[], NULL, '1d6', ARRAY['radiante']::text[], NULL, 'Muito Raro', 'Fantasia sombria / Gothic. Criado por um vampiro para dar poder a aliados mortais. Concede poderes vampiricos sem as fraquezas completas.', '{"requer":true,"descricao":"Visão no escuro 120ft. Ataque de mordida (1d6 + roubo de 1d6 HP)"}', 'Aneis Magicos', ARRAY['usos_diarios', 'vantagem', 'desvantagem', 'visao_noturna', 'luminoso']::text[], NULL, 1),
  (149, 'Amulet of Health (Amuleto da Saúde)', 'CON do portador fica em 19 (se já for maior, não muda).', ARRAY['pescoço']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Amuleto básico mas valioso que fortalece a constituição do portador acima dos limites naturais.', '{"requer":true,"descricao":"CON do portador fica em 19 (se já for maior, não muda)"}', 'Amuletos e Colares', ARRAY[]::text[], NULL, NULL),
  (150, 'Amulet of Proof Against Detection (Amuleto Contra Detecção)', 'Portador não pode ser detectado por magia de adivinhação. Localização, alinhamento e emoções ocultos. Imune a Scrying.', ARRAY['pescoço']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Amuleto essencial para ladrões, espiões e assassinos. Bloqueia rastreamento mágico.', '{"requer":true,"descricao":"Portador não pode ser detectado por magia de adivinhação. Localização, alinhamento e emoções ocultos"}', 'Amuletos e Colares', ARRAY['imunidade']::text[], NULL, NULL),
  (151, 'Amulet of the Planes (Amuleto dos Planos)', '1/dia: Plane Shift. O portador conjura o destino (CD 15 Int ou vai ao plano errado).', ARRAY['pescoço']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Muito Raro', 'Amuleto que permite viagem entre planos sem usar portais. Porém é complexo de usar e erros podem ser fatais.', '{"requer":true,"descricao":"1/dia: Plane Shift. O portador conjura o destino (CD 15 Int ou vai ao plano errado)"}', 'Amuletos e Colares', ARRAY['usos_diarios', 'teleporte']::text[], NULL, 1),
  (152, 'Necklace of Adaptation (Colar de Adaptação)', 'Portador não precisa respirar o ar ambiente: cria seu próprio suprimento. Imune a gás/veneno inalado. Pode respirar sob água.', ARRAY['pescoço']::text[], NULL, NULL, ARRAY['veneno']::text[], NULL, 'Incomum', 'Colar que cria campo de ar respirável ao redor da cabeça do portador. Essencial para ambientes hostis.', '{"requer":true,"descricao":"Portador não precisa respirar o ar ambiente: cria seu próprio suprimento. Imune a gás/veneno inalado"}', 'Amuletos e Colares', ARRAY['imunidade']::text[], NULL, NULL),
  (153, 'Necklace of Fireballs (Colar das Bolas de Fogo)', 'Contém 1d6+3 esferas. Cada esfera: Fireball de nível 3 (8d6 fogo, CD 15 Des). Pode arremessar múltiplas de uma vez (aumenta dano mas aumenta risco).', ARRAY['pescoço']::text[], NULL, '1d6+3', ARRAY['fogo']::text[], NULL, 'Raro', 'Colar cheio de esferas de vidro magicamente explosivas. Popular (e perigoso) entre aventureiros imprudentes.', NULL, 'Amuletos e Colares', ARRAY['arremessavel']::text[], NULL, NULL),
  (154, 'Periapt of Health (Periapt da Saúde)', 'Portador imune a contrair doenças e se doente fica curado automaticamente.', ARRAY['pescoço']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Periapt simples mas valioso que combate doenças. Comum entre curandeiros e aventureiros que frequentam esgoto e masmorras.', NULL, 'Amuletos e Colares', ARRAY['imunidade', 'cura']::text[], NULL, NULL),
  (155, 'Periapt of Wound Closure (Periapt de Fechamento de Feridas)', 'Portador está estabilizado automaticamente ao cair a 0 HP. Ao rolar Dados de Vida em descanso: recupera o dobro de HP.', ARRAY['pescoço']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Periapt que estanca feridas automaticamente, especialmente útil para heróis solitários.', '{"requer":true,"descricao":"Portador está estabilizado automaticamente ao cair a 0 HP. Ao rolar Dados de Vida em descanso: recupera o dobro de HP"}', 'Amuletos e Colares', ARRAY['cura']::text[], NULL, NULL),
  (156, 'Periapt of Proof Against Poison (Periapt Contra Veneno)', 'Portador imune a todos os venenos e à condição envenenado. Venenos que já afetam o portador são neutralizados imediatamente.', ARRAY['pescoço']::text[], NULL, NULL, ARRAY['veneno']::text[], NULL, 'Raro', 'Amuleto extremamente valioso em regiões de assassinos e contra criaturas peçonhentas.', NULL, 'Amuletos e Colares', ARRAY['imunidade']::text[], NULL, NULL),
  (157, 'Medallion of Thoughts (Medalhão dos Pensamentos)', '3 cargas/dia: lança Detect Thoughts (CD 13 Sab). Recupera 1d3 cargas ao amanhecer.', ARRAY['pescoço']::text[], NULL, '1d3', ARRAY[]::text[], NULL, 'Incomum', 'Amuleto que permite leitura de mentes. Usado por negociadores, interrogadores e espias da alta sociedade.', '{"requer":true,"descricao":"3 cargas/dia: lança Detect Thoughts (CD 13 Sab). Recupera 1d3 cargas ao amanhecer"}', 'Amuletos e Colares', ARRAY['cargas', 'usos_diarios', 'cura']::text[], 3, NULL),
  (158, 'Holy Symbol of Silverwing', '3 cargas. Cega e atordoa vampiros (CD 17 Sab). Mantém vampiro à luz solar (+1 rodada). Vampiro não pode entrar em forma de névoa. Recupera 1d3 ao amanhecer.', ARRAY['símbolo sagrado']::text[], NULL, '1d3', ARRAY['radiante']::text[], '{"classe":["clérigo","paladino"]}', 'Lendário', 'O símbolo sagrado usado pela lendária caçadora de vampiros Lugdana no reino de Barovia. Criado especificamente para combater Vaszlav.', '{"requer":true,"restricao_tipo":"classe","restricao":["paladino","clerigo","ladino"],"descricao":"Cega e atordoa vampiros (CD 17 Sab). Mantém vampiro à luz solar (+1 rodada)"}', 'Amuletos e Colares', ARRAY['cargas', 'cura', 'luminoso']::text[], 3, NULL),
  (159, 'Talisman of Pure Good (Talismã do Bem Puro)', '7 cargas. Portador maligno: 10d6 dano radiante ao tocar. Glifos sagrados: criatura maligna que pisar: fenda ao Abismo (morte, sem salvaguarda). Lança Holy Aura.', ARRAY['pescoço']::text[], NULL, '10d6', ARRAY['radiante']::text[], '{"alinhamento":["bom"]}', 'Artefato', 'Um dos talismãs mais poderosos e mais raros do multiverso. Criado por uma divindade do bem puro.', '{"requer":true,"restricao_tipo":"alinhamento","restricao":["bom","sagrado"],"descricao":"Portador maligno: 10d6 dano radiante ao tocar. Glifos sagrados: criatura maligna que pisar: fenda ao Abismo (morte, sem salvaguarda)"}', 'Amuletos e Colares', ARRAY['cargas', 'salvaguarda']::text[], 7, NULL),
  (160, 'Talisman of Ultimate Evil', '6 cargas. Portador bom: 10d6 dano necrótico ao tocar. Glifos sombrios: criatura boa que pisar: fenda ao Paraíso Celestial. Lança Unholy Aura.', ARRAY['pescoço']::text[], NULL, '10d6', ARRAY['necrotico']::text[], '{"alinhamento":["maligno"]}', 'Artefato', 'Contraparte maligna do Talismã do Bem Puro. Criado por uma divindade ou entidade primordial do mal.', '{"requer":true,"restricao_tipo":"alinhamento","restricao":["maligno"],"descricao":"Portador bom: 10d6 dano necrótico ao tocar. Glifos sombrios: criatura boa que pisar: fenda ao Paraíso Celestial"}', 'Amuletos e Colares', ARRAY['cargas']::text[], 6, NULL),
  (161, 'Talisman of the Sphere (Talismã da Esfera)', 'Controla a Esfera da Aniquilação com +5 em CD de controle. Permite mover a Esfera com velocidade dupla. Quem tocar a esfera é aniquilado instantaneamente.', ARRAY['pescoço']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Lendário', 'Talismã que permite controlar a Esfera da Aniquilação — um buraco negro portátil que consome tudo.', '{"requer":true,"descricao":"Controla a Esfera da Aniquilação com +5 em CD de controle. Permite mover a Esfera com velocidade dupla"}', 'Amuletos e Colares', ARRAY[]::text[], NULL, NULL),
  (162, 'Amulet of Dragon Kind', 'Dragões não atacam o portador automaticamente (percebem como igual). Vantagem em Persuasão e Intimidação contra dragões. Resistência ao sopro do tipo do dragão mais próximo.', ARRAY['pescoço']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Muito Raro', 'Fantasia dracônica. Amulet criado com escamas de 5 tipos de dragões diferentes. Concede entendimento e respeito dos dragões.', '{"requer":true,"descricao":"Dragões não atacam o portador automaticamente (percebem como igual). Vantagem em Persuasão e Intimidação contra dragões"}', 'Amuletos e Colares', ARRAY['vantagem', 'resistencia']::text[], NULL, NULL),
  (163, 'Scarab of Protection (Escaravelho de Proteção)', '12 cargas. Vantagem em salvaguardas contra magias. Imune a magias de necromancia. Ao falhar salvaguarda de necromancia: usa 1 carga para ter sucesso. Portador imune a críticos em ataques necróticos.', ARRAY['escaravelho brooch']::text[], NULL, NULL, ARRAY['necrotico']::text[], NULL, 'Lendário', 'Inspirado nos escaravelhos sagrados do Egito antigo. Proteção máxima contra magia de morte.', '{"requer":true,"descricao":"Vantagem em salvaguardas contra magias. Imune a magias de necromancia"}', 'Amuletos e Colares', ARRAY['cargas', 'imunidade', 'vantagem', 'salvaguarda']::text[], 12, NULL),
  (164, 'Necklace of Prayer Beads (Colar de Contas de Oração)', '1-6 contas (rolagem aleatória): Bless, Cure Wounds (4d8), Favor, Greater Restoration, Resurrection, Smite. Cada conta 1/dia. Recarregam ao amanhecer (70% chance por conta).', ARRAY['pescoço']::text[], NULL, '4d8', ARRAY[]::text[], '{"classe":["clérigo","druida","paladino"]}', 'Raro', 'Colar sagrado com contas encantadas. Cada conta ativa uma magia diferente. Usada por clérigos e paladinos devotos.', '{"requer":true,"restricao_tipo":"classe","restricao":["paladino","clerigo","druida","ladino"],"descricao":"1-6 contas (rolagem aleatória): Bless, Cure Wounds (4d8), Favor, Greater Restoration, Resurrection, Smite. Cada conta 1/dia"}', 'Amuletos e Colares', ARRAY['usos_diarios']::text[], NULL, 1),
  (165, 'Brooch of Shielding (Broche do Escudo)', 'Resistência a dano de força. Imune ao feitiço Magic Missile.', ARRAY['broche']::text[], NULL, NULL, ARRAY['forca']::text[], NULL, 'Incomum', 'Broche simples e útil que cria campo de força contra dano de força.', '{"requer":true,"descricao":"Resistência a dano de força. Imune ao feitiço Magic Missile"}', 'Amuletos e Colares', ARRAY['imunidade', 'resistencia']::text[], NULL, NULL),
  (166, 'Charm of the Ancients', 'Portador: Vantagem em testes de Sabedoria e Percepção. Pode falar com espíritos ancestrais (1/dia: Speak with Dead em qualquer linguagem). Vantagem em salvaguardas de charme.', ARRAY['pingente']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Fantasia ancestral / tribal. Criado por xamãs ancestrais usando ossos de criaturas antigas e penas de aves extintas.', '{"requer":true,"descricao":"Portador: Vantagem em testes de Sabedoria e Percepção. Pode falar com espíritos ancestrais (1/dia: Speak with Dead em qualquer linguagem)"}', 'Amuletos e Colares', ARRAY['usos_diarios', 'vantagem', 'salvaguarda']::text[], NULL, 1),
  (167, 'Staff of Power (Cajado do Poder)', '+2 em ataque/dano como arma. 20 cargas: Cone of Cold, Fireball (nível 5), Globe of Invulnerability, Hold Monster, Levitation, Lightning Bolt (nível 5), Magic Missile (nível 5), Ray of Enfeeblement, Wall of Force. Retribalization: explodir (1 em 20 chance, 17d8 dano de força 30ft).', ARRAY['foco arcano', 'arma']::text[], '{"ataque":2,"dano":2}', '17d8', ARRAY['fogo', 'gelo', 'relampago', 'forca']::text[], '{"classe":["conjurador"]}', 'Muito Raro', 'Um dos cajados mais poderosos para conjuradores. Reúne múltiplas magias ofensivas e defensivas em um único item.', '{"requer":true,"restricao_tipo":"classe","restricao":["conjurador"],"descricao":"+2 em ataque/dano como arma. 20 cargas: Cone of Cold, Fireball (nível 5), Globe of Invulnerability, Hold Monster, Levitation, Lightning Bolt (nível 5), Magic Missile (nível 5), Ray of Enfeeblement, Wall of Force"}', 'Cajados, Varinhas e Orbes', ARRAY['cargas', 'luminoso']::text[], 20, NULL),
  (168, 'Staff of the Magi (Cajado do Mago)', '+2 em ataque/dano. 50 cargas: todas as magias do Staff of Power + Conjure Elemental, Dispel Magic, Fireball (nível 7), Flaming Sphere, Ice Storm, Invisibility, Knock, Web, Wall of Fire. Absorve magias: quando mirado por magia, pode absorver (recupera cargas).', ARRAY['foco arcano', 'arma']::text[], '{"ataque":2,"dano":2}', NULL, ARRAY['fogo']::text[], '{"classe":["mago"]}', 'Lendário', 'O cajado definitivo dos magos. Contém o maior arsenal de magias de qualquer cajado existente.', '{"requer":true,"restricao_tipo":"classe","restricao":["mago"],"descricao":"+2 em ataque/dano. 50 cargas: todas as magias do Staff of Power + Conjure Elemental, Dispel Magic, Fireball (nível 7), Flaming Sphere, Ice Storm, Invisibility, Knock, Web, Wall of Fire"}', 'Cajados, Varinhas e Orbes', ARRAY['cargas', 'cura', 'invisibilidade']::text[], 50, NULL),
  (169, 'Staff of Healing (Cajado da Cura)', '10 cargas: Cure Wounds (1-4 cargas), Lesser Restoration (2), Mass Cure Wounds (5). Recupera 1d6+4 ao amanhecer.', ARRAY['foco divino', 'arma']::text[], NULL, '1d6+4', ARRAY[]::text[], '{"classe":["bardo","clérigo","druida"]}', 'Raro', 'Cajado sagrado para curandeiros. Criado em templos de deuses da vida por sacerdotes de alta devoção.', '{"requer":true,"restricao_tipo":"classe","restricao":["clerigo","druida","bardo"],"descricao":"10 cargas: Cure Wounds (1-4 cargas), Lesser Restoration (2), Mass Cure Wounds (5). Recupera 1d6+4 ao amanhecer"}', 'Cajados, Varinhas e Orbes', ARRAY['cargas', 'cura']::text[], 10, NULL),
  (170, 'Staff of Fire (Cajado do Fogo)', 'Resistência a fogo. 10 cargas: Burning Hands (1), Fireball (3), Wall of Fire (4). Recupera 1d6+4 ao amanhecer.', ARRAY['foco arcano', 'arma']::text[], NULL, '1d6+4', ARRAY['fogo']::text[], '{"classe":["druida","feiticeiro","mago"]}', 'Muito Raro', 'Cajado imbuído com elementais de fogo. Popular entre piromantes e magos de combate.', '{"requer":true,"restricao_tipo":"classe","restricao":["mago","feiticeiro","bruxo","druida"],"descricao":"Resistência a fogo. 10 cargas: Burning Hands (1), Fireball (3), Wall of Fire (4)"}', 'Cajados, Varinhas e Orbes', ARRAY['cargas', 'resistencia', 'cura']::text[], 10, NULL),
  (171, 'Staff of Frost (Cajado do Gelo)', 'Resistência a frio. 10 cargas: Cone of Cold (5), Fog Cloud (1), Ice Storm (4), Wall of Ice (4). Recupera 1d6+4 ao amanhecer.', ARRAY['foco arcano', 'arma']::text[], NULL, '1d6+4', ARRAY['gelo']::text[], '{"classe":["druida","feiticeiro","mago"]}', 'Muito Raro', 'Cajado criomágico para mestres do gelo. Emite névoa fria ao ser empunhado.', '{"requer":true,"restricao_tipo":"classe","restricao":["mago","feiticeiro","bruxo","druida"],"descricao":"Resistência a frio. 10 cargas: Cone of Cold (5), Fog Cloud (1), Ice Storm (4), Wall of Ice (4)"}', 'Cajados, Varinhas e Orbes', ARRAY['cargas', 'resistencia', 'cura']::text[], 10, NULL),
  (172, 'Staff of Thunder and Lightning (Cajado do Trovão e Relâmpago)', 'Thunder: +2d6 trovão ao acertar. Lightning: 9d6 de relâmpago linha (CD 17 Des). Thunderclap: 2d6 trovão 10ft ao redor. Thunder and Lightning: +2d6 trovão + relâmpago no mesmo alvo. Storm: Tempestade local 1/semana. Cada poder: 1/dia.', ARRAY['arma', 'foco']::text[], NULL, '2d6', ARRAY['trovao', 'relampago']::text[], NULL, 'Muito Raro', 'Cajado de ataque e poder elemental. Incita tempestades locais com seu uso.', '{"requer":true,"descricao":"Thunder: +2d6 trovão ao acertar. Lightning: 9d6 de relâmpago linha (CD 17 Des)"}', 'Cajados, Varinhas e Orbes', ARRAY['usos_diarios', 'luminoso']::text[], NULL, 1),
  (173, 'Staff of Charming (Cajado do Encantamento)', '10 cargas: Charm Person (1), Command (1), Comprehend Languages (1), Dominate Person (5), Mass Suggestion (6), Suggestion (2). Resistência contra charme quando segura.', ARRAY['foco arcano', 'arma']::text[], NULL, NULL, ARRAY[]::text[], '{"classe":["bardo","clérigo","druida","feiticeiro","mago"]}', 'Raro', 'Cajado diplomático e manipulador. Favorito de bardos, políticos e vilões charmosos.', '{"requer":true,"restricao_tipo":"classe","restricao":["clerigo","mago","feiticeiro","bruxo","druida","bardo"],"descricao":"10 cargas: Charm Person (1), Command (1), Comprehend Languages (1), Dominate Person (5), Mass Suggestion (6), Suggestion (2). Resistência contra charme quando segura"}', 'Cajados, Varinhas e Orbes', ARRAY['cargas', 'resistencia']::text[], 10, NULL),
  (174, 'Wand of Fireballs (Varinha das Bolas de Fogo)', '7 cargas: lança Fireball (nível 3 por padrão; pode gastar 1-3 cargas extras para aumentar o nível). Recupera 1d6+1 ao amanhecer.', ARRAY['varinha']::text[], NULL, '1d6+1', ARRAY['fogo']::text[], '{"classe":["conjurador"]}', 'Raro', 'Varinha clássica para conjuradores de combate. Fácil de usar e devastadora em grupos.', '{"requer":true,"restricao_tipo":"classe","restricao":["conjurador"],"descricao":"7 cargas: lança Fireball (nível 3 por padrão; pode gastar 1-3 cargas extras para aumentar o nível). Recupera 1d6+1 ao amanhecer"}', 'Cajados, Varinhas e Orbes', ARRAY['cargas', 'cura']::text[], 7, NULL),
  (175, 'Wand of Lightning Bolts (Varinha dos Relâmpagos)', '7 cargas: lança Lightning Bolt (nível 3 base; pode gastar extras). Recupera 1d6+1 ao amanhecer.', ARRAY['varinha']::text[], NULL, '1d6+1', ARRAY['relampago']::text[], '{"classe":["conjurador"]}', 'Raro', 'Versão elétrica da Varinha das Bolas de Fogo. Preferida em áreas fechadas.', '{"requer":true,"restricao_tipo":"classe","restricao":["conjurador"],"descricao":"7 cargas: lança Lightning Bolt (nível 3 base; pode gastar extras). Recupera 1d6+1 ao amanhecer"}', 'Cajados, Varinhas e Orbes', ARRAY['cargas', 'cura', 'luminoso']::text[], 7, NULL),
  (176, 'Wand of Magic Missiles (Varinha dos Mísseis Mágicos)', '7 cargas: lança Magic Missile (nível 1 base; até 6 cargas para nível mais alto). Recupera 1d6+1 ao amanhecer.', ARRAY['varinha']::text[], NULL, '1d6+1', ARRAY[]::text[], '{"classe":["conjurador"]}', 'Incomum', 'Varinha básica e confiável. O Magic Missile nunca erra — e a varinha potencializa isso.', '{"requer":true,"restricao_tipo":"classe","restricao":["conjurador"],"descricao":"7 cargas: lança Magic Missile (nível 1 base; até 6 cargas para nível mais alto). Recupera 1d6+1 ao amanhecer"}', 'Cajados, Varinhas e Orbes', ARRAY['cargas', 'cura']::text[], 7, NULL),
  (177, 'Wand of Paralysis (Varinha da Paralisia)', '7 cargas: raio de paralisia (CD 15 Con ou fica paralisado por 1 minuto; pode repetir salvaguarda ao final de cada turno). Recupera 1d6+1 ao amanhecer.', ARRAY['varinha']::text[], NULL, '1d6+1', ARRAY[]::text[], '{"classe":["conjurador"]}', 'Raro', 'Varinha de controle de batalha. Capturar inimigos vivos ou parar ameaças instantaneamente.', '{"requer":true,"restricao_tipo":"classe","restricao":["conjurador"],"descricao":"7 cargas: raio de paralisia (CD 15 Con ou fica paralisado por 1 minuto; pode repetir salvaguarda ao final de cada turno). Recupera 1d6+1 ao amanhecer"}', 'Cajados, Varinhas e Orbes', ARRAY['cargas', 'cura', 'salvaguarda']::text[], 7, NULL),
  (178, 'Wand of Polymorph (Varinha do Polimorfismo)', '5 cargas: lança Polymorph (CD 15 Sab para resistir). Recupera 1d4+1 ao amanhecer.', ARRAY['varinha']::text[], NULL, '1d4+1', ARRAY[]::text[], '{"classe":["conjurador"]}', 'Muito Raro', 'Varinha para transformar amigos, inimigos e a si mesmo. Uma das varinhas mais versáteis existentes.', '{"requer":true,"restricao_tipo":"classe","restricao":["conjurador"],"descricao":"5 cargas: lança Polymorph (CD 15 Sab para resistir). Recupera 1d4+1 ao amanhecer"}', 'Cajados, Varinhas e Orbes', ARRAY['cargas', 'cura']::text[], 5, NULL),
  (179, 'Wand of Wonder (Varinha das Maravilhas)', '7 cargas: ao usar, rola 1d100 para efeito aleatório (tabela de 100 opções — desde criar grama até summoning, desde encolher o alvo até a chuva de rubis). Total caos controlado.', ARRAY['varinha']::text[], NULL, '1d100', ARRAY[]::text[], '{"classe":["conjurador"]}', 'Raro', 'A varinha mais imprevisível do multiverso. Cada uso rola em tabela de 100 efeitos aleatórios.', '{"requer":true,"restricao_tipo":"classe","restricao":["conjurador"],"descricao":"7 cargas: ao usar, rola 1d100 para efeito aleatório (tabela de 100 opções — desde criar grama até summoning, desde encolher o alvo até a chuva de rubis). Total caos controlado"}', 'Cajados, Varinhas e Orbes', ARRAY['cargas', 'invocacao']::text[], 7, NULL),
  (180, 'Wand of Secrets (Varinha dos Segredos)', '3 cargas/dia: aponta para a porta secreta, passagem ou armadilha mais próxima em 30ft (se houver alguma). Recupera 1d3 ao amanhecer.', ARRAY['varinha']::text[], NULL, '1d3', ARRAY[]::text[], NULL, 'Incomum', 'Varinha simples mas essencial para exploradores de masmorras. Detecta o invisível.', NULL, 'Cajados, Varinhas e Orbes', ARRAY['cargas', 'usos_diarios', 'cura']::text[], 3, NULL),
  (181, 'Orb of Dragonkind (Orbe dos Dragões)', 'Lança ESP, Fear, Dominate Monster (vs. dragões, CD 18). Convoca e controla dragões em 40 milhas. Portador caótico maligno: pode usar sem risco. Outros arriscam ser dominados pela orbe.', ARRAY['item mágico']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Artefato', 'Cinco Orbes foram criados pelos magos de Istar para controlar dragões cromáticos. Cada um controla um tipo de dragão.', '{"requer":true,"restricao_tipo":"especial","restricao":["complexo e perigoso"],"descricao":"Lança ESP, Fear, Dominate Monster (vs. dragões, CD 18)"}', 'Cajados, Varinhas e Orbes', ARRAY['bonus_ca', 'invocacao']::text[], NULL, NULL),
  (182, 'Crystal Ball (Bola de Cristal)', '1/dia: Scrying (CD 17 Sab). Versões lendárias: True Seeing, Telepathy ou vantagem em qualquer adivinhação.', ARRAY['foco de adivinhação']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Muito Raro / Lendário', 'A clássica bola de cristal dos videntes. Versões comuns permitem Scrying; versões raras adicionam outros poderes.', '{"requer":true,"descricao":"1/dia: Scrying (CD 17 Sab). Versões lendárias: True Seeing, Telepathy ou vantagem em qualquer adivinhação"}', 'Cajados, Varinhas e Orbes', ARRAY['usos_diarios', 'vantagem']::text[], NULL, 1),
  (183, 'Staff of the Woodlands (Cajado da Floresta)', 'Fincado no chão: cria Árvore Mágica (como Treestride). 10 cargas: Animal Friendship (1), Awaken (5), Barkskin (2), Locate Animals/Plants (2), Speak with Animals (1), Speak with Plants (3), Wall of Thorns (6). Recupera 1d6+4 ao amanhecer.', ARRAY['foco druídico', 'arma']::text[], NULL, '1d6+4', ARRAY[]::text[], '{"classe":["druida"]}', 'Raro', 'O cajado dos druidas florestais. Encantado com a energia de árvores anciais vivas.', '{"requer":true,"restricao_tipo":"classe","restricao":["druida"],"descricao":"Fincado no chão: cria Árvore Mágica (como Treestride). 10 cargas: Animal Friendship (1), Awaken (5), Barkskin (2), Locate Animals/Plants (2), Speak with Animals (1), Speak with Plants (3), Wall of Thorns (6)"}', 'Cajados, Varinhas e Orbes', ARRAY['cargas', 'cura']::text[], 10, NULL),
  (184, 'Wand of Binding (Varinha da Prisão)', '7 cargas: Hold Monster (5), Hold Person (2). Recupera 1d6+1 ao amanhecer.', ARRAY['varinha']::text[], NULL, '1d6+1', ARRAY[]::text[], '{"classe":["conjurador"]}', 'Raro', 'Varinha para aprisionar e deter inimigos. Popular entre capturadores de monstros e negociantes de bestiário.', '{"requer":true,"restricao_tipo":"classe","restricao":["conjurador"],"descricao":"7 cargas: Hold Monster (5), Hold Person (2). Recupera 1d6+1 ao amanhecer"}', 'Cajados, Varinhas e Orbes', ARRAY['cargas', 'cura']::text[], 7, NULL),
  (185, 'Rod of Lordly Might (Bastão do Poder Senhorial)', '6 formas: Flail (+3), Spear (+3), Battle Axe (+3), Handaxe x2, Club (+3, atordoa), Drain Life (CD 17 Con ou 4d6 necrótico). Detalhes de cada forma com botões específicos.', ARRAY['arma mágica versátil']::text[], NULL, '4d6', ARRAY['necrotico']::text[], NULL, 'Lendário', 'Bastão multi-forma que muda de arma conforme necessidade. Uma das seis formas pode ser selecionada como ação bônus.', '{"requer":true,"descricao":"6 formas: Flail (+3), Spear (+3), Battle Axe (+3), Handaxe x2, Club (+3, atordoa), Drain Life (CD 17 Con ou 4d6 necrótico). Detalhes de cada forma com botões específicos"}', 'Cajados, Varinhas e Orbes', ARRAY[]::text[], NULL, NULL),
  (186, 'Rod of Absorption (Bastão da Absorção)', '50 cargas totais (não recupera). Absorve magias que miram somente o portador: converte em slots de magia equivalentes (portador pode gastar). Ao atingir 50 cargas absorvidas: fica inerte.', ARRAY['bastão']::text[], NULL, NULL, ARRAY[]::text[], '{"classe":["conjurador"]}', 'Muito Raro', 'Bastão que absorve magias que miram o portador e transforma em cargas de Wish ou slots de magia.', '{"requer":true,"restricao_tipo":"classe","restricao":["conjurador"],"descricao":"50 cargas totais (não recupera). Absorve magias que miram somente o portador: converte em slots de magia equivalentes (portador pode gastar)"}', 'Cajados, Varinhas e Orbes', ARRAY['cargas', 'cura']::text[], 50, NULL),
  (187, 'Staff of Striking (Cajado dos Golpes)', '+3 em ataque/dano como arma. 10 cargas: ao acertar, gastar 1-3 cargas para adicionar 1d6 de força por carga. Recupera 1d6+4 ao amanhecer.', ARRAY['arma']::text[], '{"ataque":3,"dano":3}', '1d6', ARRAY['forca']::text[], NULL, 'Muito Raro', 'Cajado de combate corpo a corpo para quem quer poder arcano em combate físico.', '{"requer":true,"descricao":"+3 em ataque/dano como arma. 10 cargas: ao acertar, gastar 1-3 cargas para adicionar 1d6 de força por carga"}', 'Cajados, Varinhas e Orbes', ARRAY['cargas', 'cura']::text[], 10, NULL),
  (188, 'Potion of Healing (Poção de Cura)', 'Recupera 2d4+2 HP. Variedades: Greater (4d4+4), Superior (8d4+8), Supreme (10d4+20).', ARRAY['poção']::text[], NULL, '2d4+2', ARRAY[]::text[], NULL, 'Comum', 'A mais básica e mais usada de todas as poções. Encontrada em qualquer loja de aventureiros e produzida por curandeiros em todo mundo.', NULL, 'Pocoes e Elixires', ARRAY['cura']::text[], NULL, NULL),
  (189, 'Potion of Giant Strength (Poção da Força de Gigante)', 'FOR do portador aumenta para o valor do tipo por 1 hora.', ARRAY['poção']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum a Lendário', 'Brewed com glândulas de gigantes. Tipos diferentes baseados no tipo de gigante: Hill (21 FOR), Frost/Stone (23), Fire (25), Cloud (27), Storm (29).', NULL, 'Pocoes e Elixires', ARRAY[]::text[], NULL, NULL),
  (190, 'Potion of Invisibility (Poção de Invisibilidade)', 'Invisibilidade por 1 hora (rompe ao atacar ou conjurar, mas retorna após a ação).', ARRAY['poção']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Muito Raro', 'Poção de destilado de fadas invisíveis e cristais do Plano Etéreo.', NULL, 'Pocoes e Elixires', ARRAY['invisibilidade', 'retorno']::text[], NULL, NULL),
  (191, 'Potion of Flying (Poção do Voo)', 'Velocidade de voo igual à de terreno por 1 hora.', ARRAY['poção']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Muito Raro', 'Feita com plumas de anjo e essência de elemental de ar. Permite voo por 1 hora.', NULL, 'Pocoes e Elixires', ARRAY['voo']::text[], NULL, NULL),
  (192, 'Potion of Speed (Poção da Velocidade)', 'Efeitos de Haste por 1 minuto (velocidade dobrada, +2 CA, vantagem em Des, ação extra por rodada).', ARRAY['poção']::text[], '{"ca":2}', NULL, ARRAY[]::text[], NULL, 'Muito Raro', 'Equivalente bebível do feitiço Haste. Acelera o metabolismo magicamente.', NULL, 'Pocoes e Elixires', ARRAY['vantagem', 'bonus_ca']::text[], NULL, NULL),
  (193, 'Potion of Gaseous Form (Poção da Forma Gasosa)', 'Forma Gasosa por 1 hora ou até dissipar. Pode voar 10ft, atravessar frestas, imune a dano não mágico.', ARRAY['poção']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Permite ao portador tornar-se névoa temporariamente. Útil para escapar de prisões e infiltrar locais.', NULL, 'Pocoes e Elixires', ARRAY['imunidade', 'voo']::text[], NULL, NULL),
  (194, 'Potion of Diminution (Poção da Diminuição)', 'Encolhe portador para tamanho Minúsculo por 1d4 horas. Itens encolhem junto. Desvantagem em FOR.', ARRAY['poção']::text[], NULL, '1d4', ARRAY[]::text[], NULL, 'Raro', 'Reduz o portador. Útil para entrar em lugares inacessíveis a tamanho normal.', NULL, 'Pocoes e Elixires', ARRAY['vantagem', 'desvantagem']::text[], NULL, NULL),
  (195, 'Potion of Growth (Poção do Crescimento)', 'Tamanho Grande por 1d4 horas. Vantagem em FOR, desvantagem em Furtividade. Armas causam 1d4 extra.', ARRAY['poção']::text[], NULL, '1d4', ARRAY[]::text[], NULL, 'Incomum', 'Aumenta o portador para tamanho Grande.', NULL, 'Pocoes e Elixires', ARRAY['vantagem', 'desvantagem']::text[], NULL, NULL),
  (196, 'Potion of Water Breathing (Poção de Respirar na Água)', 'Respirar embaixo d''água por 1 hora.', ARRAY['poção']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Feita com guelras de tritões e algas profundas. Popular em cidades costeiras.', NULL, 'Pocoes e Elixires', ARRAY[]::text[], NULL, NULL),
  (197, 'Potion of Mind Reading (Poção da Leitura Mental)', 'Detect Thoughts ativo por 10 minutos (CD 13 Sab para resistir).', ARRAY['poção']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Feita com fragmentos de Sorvedor (Sorvedor de Mentes) diluídos em solução arcana.', NULL, 'Pocoes e Elixires', ARRAY[]::text[], NULL, NULL),
  (198, 'Potion of Resistance (Poção de Resistência)', 'Resistência a um tipo de dano por 1 hora (tipo sorteado ao criar: ácido, frio, fogo, relâmpago, etc.).', ARRAY['poção']::text[], NULL, NULL, ARRAY['fogo', 'gelo', 'relampago', 'acido']::text[], NULL, 'Incomum', 'Feita com elementos resistentes a um tipo de dano. Tipo definido ao fazer.', NULL, 'Pocoes e Elixires', ARRAY['resistencia']::text[], NULL, NULL),
  (199, 'Potion of Animal Friendship (Poção de Amizade com Animais)', 'Lança Animal Friendship com CD 13 por 1 hora.', ARRAY['poção']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Feita por druidas usando ervas raras e mel de abelhas fadas. Popular entre exploradores.', NULL, 'Pocoes e Elixires', ARRAY[]::text[], NULL, NULL),
  (200, 'Potion of Clairvoyance (Poção da Clarividência)', 'Clairvoyance (ouvido ou visão invisível em local familiar ou geral) por 10 minutos.', ARRAY['poção']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Feita com o terceiro olho de um vigia abissal ou cristal de clarividência puro.', NULL, 'Pocoes e Elixires', ARRAY[]::text[], NULL, NULL),
  (201, 'Potion of Vitality (Poção da Vitalidade)', 'Cura todas as doenças, remove o veneno e todos os níveis de exaustão. Recupera HP máximo.', ARRAY['poção']::text[], NULL, NULL, ARRAY['veneno']::text[], NULL, 'Muito Raro', 'Remove exaustão e doenças instantaneamente. Extremamente cara.', NULL, 'Pocoes e Elixires', ARRAY['cura']::text[], NULL, NULL),
  (202, 'Potion of Longevity (Poção da Longevidade)', 'Reduz a idade do portador em 1d6+6 anos (mínimo 13 anos). Há 10% de chance de reação oposta (envelhece).', ARRAY['poção']::text[], NULL, '1d6+6', ARRAY[]::text[], NULL, 'Muito Raro', 'Poção que reverte o envelhecimento. Cobiçada por nobres e magos idosos.', NULL, 'Pocoes e Elixires', ARRAY[]::text[], NULL, NULL),
  (203, 'Elixir of Health (Elixir da Saúde)', 'Remove todas as doenças, cegueira, surdez, paralisia, veneno e condição envenenada.', ARRAY['poção']::text[], NULL, NULL, ARRAY['veneno']::text[], NULL, 'Raro', 'Mais completo que um simples antídoto — remove todos os status negativos de uma vez.', NULL, 'Pocoes e Elixires', ARRAY[]::text[], NULL, NULL),
  (204, 'Oil of Slipperiness (Óleo da Escorregadeira)', 'Aplicado no corpo: imune a agarramento e movimentos restritos por 8 horas. Derramado no chão: Grease em área de 10ft por 8 horas.', ARRAY['óleo']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Pode ser aplicado no corpo ou no chão. Múltiplos usos táticos.', NULL, 'Pocoes e Elixires', ARRAY['imunidade']::text[], NULL, NULL),
  (205, 'Oil of Sharpness (Óleo da Nitidez)', 'Arma ou 20 munições: +3 em ataque e dano por 1 hora. Trata-se como mágica.', ARRAY['óleo']::text[], '{"ataque":3,"dano":3}', NULL, ARRAY[]::text[], NULL, 'Muito Raro', 'Óleo que temporariamente dá à arma tratada qualidade de +3.', NULL, 'Pocoes e Elixires', ARRAY[]::text[], NULL, NULL),
  (206, 'Oil of Etherealness (Óleo Etéreo)', 'Aplica no corpo (10 minutos): Etherealness por 1 hora (incl. roupas e itens carregados).', ARRAY['óleo']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Torna o portador etéreo temporariamente.', NULL, 'Pocoes e Elixires', ARRAY[]::text[], NULL, NULL),
  (207, 'Philter of Love (Filtro do Amor)', 'Portador fica encantado (em adoração) pela primeira criatura que ver por 1 hora. Completamente consentido pelo portador (sem teste de resistência).', ARRAY['poção']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Poção de encantamento clássica. A primeira criatura vista após beber será amada pelo portador por 1 hora.', NULL, 'Pocoes e Elixires', ARRAY['resistencia']::text[], NULL, NULL),
  (208, 'Potion of Heroism (Poção do Heroísmo)', 'Imune ao medo. +10 HP temporários por 1 hora.', ARRAY['poção']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Poção que eleva o portador além de seus limites normais durante a batalha.', NULL, 'Pocoes e Elixires', ARRAY['imunidade']::text[], NULL, NULL),
  (209, 'Sovereign Glue (Cola Soberana)', 'Une permanentemente dois objetos. Impossível separar sem Universal Solvent. 1d6+1 aplicações por frasco.', ARRAY['adesivo']::text[], NULL, '1d6+1', ARRAY[]::text[], NULL, 'Lendário', 'Cola que une qualquer dois objetos de forma permanente. Somente o Universal Solvent pode dissolvê-la.', NULL, 'Pocoes e Elixires', ARRAY[]::text[], NULL, NULL),
  (210, 'Universal Solvent (Solvente Universal)', 'Dissolve qualquer cola, incluindo Sovereign Glue. Dissolve Sovereign Glue magicamente. 1 oz dissolve até 1 pé quadrado de cola por aplicação.', ARRAY['dissolvent']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Lendário', 'A contrapartida da Cola Soberana. Dissolve qualquer adesivo ou ligação física.', NULL, 'Pocoes e Elixires', ARRAY[]::text[], NULL, NULL),
  (211, 'Bag of Holding (Bolsa do Segurar)', 'Dimensões externas: 2ft de diâmetro, 4ft de profundidade. Pode carregar até 500 lb / 64 pés cúbicos. Itens em peso apontam 15 lb. Se perfurada: tragada para o Plano Astral.', ARRAY['bolsa']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Um dos itens mais icônicos de D&D. Muito maior por dentro do que por fora — contém um espaço extradimensional.', NULL, 'Itens de Uso e Ferramentas Magicas', ARRAY[]::text[], NULL, NULL),
  (212, 'Handy Haversack (Mochila Conveniente)', '3 compartimentos extradimensionais (2 laterais: 20 lb/2 pés³ cada; 1 central: 80 lb/8 pés³). Item desejado sempre vem à mão imediatamente.', ARRAY['mochila']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Mochila que sempre coloca na mão certa o item desejado. Similar à Bag of Holding mas mais organizada.', NULL, 'Itens de Uso e Ferramentas Magicas', ARRAY[]::text[], NULL, NULL),
  (213, 'Portable Hole (Buraco Portátil)', 'Círculo de 6ft de diâmetro. Cria espaço extradimensional de 10ft de profundidade. Se colocado em Bag of Holding: sucção transporta tudo para Plano Astral.', ARRAY['pano']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Peça de seda negra que cria um buraco extradimensional ao ser aberta. Perfeito para armazenamento e infiltração.', NULL, 'Itens de Uso e Ferramentas Magicas', ARRAY[]::text[], NULL, NULL),
  (214, 'Immovable Rod (Bastão Imóvel)', 'Botão: bastão fica imóvel no ar (como se ancorado ao plano). Suporta até 8.000 lb antes de mover. 5 criaturas conseguem mover com CD 30.', ARRAY['bastão']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Bastão que trava em posição absolutamente fixa no espaço. Usos criativos infinitos.', NULL, 'Itens de Uso e Ferramentas Magicas', ARRAY[]::text[], NULL, NULL),
  (215, 'Rope of Entanglement (Corda do Enlaçamento)', '30ft de comprimento. Comando: corda prende criatura alvo (CD 15 Des ou For para escapar por turno). A corda tem CA 20, 20 HP e resistência a dano contundente.', ARRAY['corda']::text[], '{"ca_base":20}', NULL, ARRAY[]::text[], NULL, 'Raro', 'Corda mágica que se enrolada no inimigo prende-o com força sobrenatural.', NULL, 'Itens de Uso e Ferramentas Magicas', ARRAY['resistencia', 'bonus_ca']::text[], NULL, NULL),
  (216, 'Rope of Climbing (Corda de Escalada)', '60ft de comprimento. Comando: a corda se move (60ft por round), amarra a si mesma, sobe por superfícies, etc. Suporta 3.000 lb.', ARRAY['corda']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Corda que obedece ao portador como uma cobra obediente.', NULL, 'Itens de Uso e Ferramentas Magicas', ARRAY[]::text[], NULL, NULL),
  (217, 'Decanter of Endless Water (Decanter de Água Infinita)', '''Torneira'': 1 galão/round. ''Fonte'': 5 galões/round. ''Geyser'': 30 galões/round (cone de 30ft, CD 13 STR ou vai ao chão). A água é mundana.', ARRAY['garrafa']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Garrafa que produz água infinitamente. Três palavras de comando: fluxo diferente.', NULL, 'Itens de Uso e Ferramentas Magicas', ARRAY[]::text[], NULL, NULL),
  (218, 'Alchemy Jug (Jarro da Alquimia)', '1/dia produz: ácido (8 oz), água benta (4), óleo (1 quart), veneno básico (1/2 oz), cerveja (4 galões), mel (1 galão), leite (2), vinagre (2), vinho (1 galão), água fresca (8 galões).', ARRAY['jarro']::text[], NULL, NULL, ARRAY['acido', 'veneno']::text[], NULL, 'Incomum', 'Jarro que produz qualquer líquido mundano uma vez por dia.', NULL, 'Itens de Uso e Ferramentas Magicas', ARRAY['usos_diarios']::text[], NULL, 1),
  (219, 'Bag of Tricks (Bolsa dos Truques)', '3/dia: extrai miniatura → animal real por 1 hora (ou até HP zero). Cinza: rato, corvo, vison, javali, urso negro, gato montês, abutre; variantes de tamanho crescente.', ARRAY['bolsa']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Bolsa que contém miniaturas que viram animais reais. Existem 3 versões: cinza, ferrugem e marrom.', NULL, 'Itens de Uso e Ferramentas Magicas', ARRAY['usos_diarios']::text[], NULL, 3),
  (220, 'Cube of Force (Cubo da Força)', '6 faces, 6 efeitos. Gasta cargas para manter o cubo ativo. Bloqueios vão de ''bloqueia gás e névoa'' até ''bloqueia todos os efeitos mágicos''. 36 cargas, recupera 1d20 ao amanhecer.', ARRAY['cubo']::text[], NULL, '1d20', ARRAY[]::text[], NULL, 'Raro', 'Cubo que cria uma barreira invisível de força ao redor do portador.', '{"requer":true,"descricao":"6 faces, 6 efeitos. Gasta cargas para manter o cubo ativo"}', 'Itens de Uso e Ferramentas Magicas', ARRAY['cargas', 'cura']::text[], 36, NULL),
  (221, 'Eversmoking Bottle (Garrafa do Fumo Eterno)', 'Aberta: emite fumaça pesada (área fortemente obscurecida, cresce 10ft/round até cobrir área de 60ft de raio). Só para ao fechar e demorar 10 minutos para dissipar.', ARRAY['garrafa']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Garrafa que emite fumaça infinita. Pode obscurecer uma área inteira.', NULL, 'Itens de Uso e Ferramentas Magicas', ARRAY[]::text[], NULL, NULL),
  (222, 'Eyes of Minute Seeing (Óculos da Visão Minuciosa)', 'Vantagem em testes de Investigação ao examinar objetos ou documentos de perto.', ARRAY['óculos']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Lentes encantadas para ver detalhes microscópicos. Favoritas de joalheiros e armeiros.', NULL, 'Itens de Uso e Ferramentas Magicas', ARRAY['vantagem']::text[], NULL, NULL),
  (223, 'Eyes of the Eagle (Óculos da Águia)', 'Vantagem em Percepção (visão). Pode ver com detalhes a até 1 milha de distância.', ARRAY['óculos']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Lentes que ampliam a visão para distâncias extremas como uma águia.', '{"requer":true,"descricao":"Vantagem em Percepção (visão). Pode ver com detalhes a até 1 milha de distância"}', 'Itens de Uso e Ferramentas Magicas', ARRAY['vantagem']::text[], NULL, NULL),
  (224, 'Goggles of Night (Óculos da Noite)', 'Visão no escuro de 60ft. Se já tiver visão no escuro: estende em 60ft.', ARRAY['óculos']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Óculos que concedem visão no escuro, populares entre raças que naturalmente não têm essa capacidade.', NULL, 'Itens de Uso e Ferramentas Magicas', ARRAY['visao_noturna']::text[], NULL, NULL),
  (225, 'Cape of the Mountebank (Manto do Charlatão)', '1/dia: Dimension Door (teleporta até 500ft). Deixa rastro de fumaça colorida no local de partida e chegada.', ARRAY['manto']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Manto com poderes de teleportação. Favorito de ladrões e artistas.', NULL, 'Itens de Uso e Ferramentas Magicas', ARRAY['usos_diarios', 'teleporte']::text[], NULL, 1),
  (226, 'Boots of Elvenkind (Botas Élficas)', 'Movimentos silenciosos: vantagem em Furtividade (som dos passos). Passadas não fazem barulho mesmo em superfícies barulhentas.', ARRAY['botas']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Botas que absorvem o som dos passos. Feitas por artesãos elfos com couro de unicórnio.', NULL, 'Itens de Uso e Ferramentas Magicas', ARRAY['vantagem']::text[], NULL, NULL),
  (227, 'Boots of Speed (Botas da Velocidade)', 'Clique do calcanhar: velocidade dobrada por 10 minutos e Ataque de Oportunidade contra portador tem desvantagem. Após 10 min: exaustas até descanso longo.', ARRAY['botas']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Botas que dobram a velocidade de movimento temporariamente.', '{"requer":true,"descricao":"Clique do calcanhar: velocidade dobrada por 10 minutos e Ataque de Oportunidade contra portador tem desvantagem. Após 10 min: exaustas até descanso longo"}', 'Itens de Uso e Ferramentas Magicas', ARRAY['vantagem', 'desvantagem']::text[], NULL, NULL),
  (228, 'Boots of Striding and Sprinting (Botas de Passos e Corrida)', 'Velocidade mínima de 30ft em qualquer terreno (mesmo difícil). Ao correr: velocidade triplicada por 1 rodada (1/turno).', ARRAY['botas']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Botas que garantem velocidade mínima mesmo em terreno difícil.', '{"requer":true,"descricao":"Velocidade mínima de 30ft em qualquer terreno (mesmo difícil). Ao correr: velocidade triplicada por 1 rodada (1/turno)"}', 'Itens de Uso e Ferramentas Magicas', ARRAY[]::text[], NULL, NULL),
  (229, 'Winged Boots (Botas Aladas)', 'Velocidade de voo igual à de terra por até 4 horas/dia (uso descontínuo OK). Recarrega 2 horas/hora de descanso.', ARRAY['botas']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Botas com asas que concedem voo temporário.', '{"requer":true,"descricao":"Velocidade de voo igual à de terra por até 4 horas/dia (uso descontínuo OK). Recarrega 2 horas/hora de descanso"}', 'Itens de Uso e Ferramentas Magicas', ARRAY['usos_diarios', 'voo']::text[], NULL, NULL),
  (230, 'Gloves of Missile Snaring (Luvas da Interceptação de Projéteis)', 'Como reação quando atingido por projétil: reduz dano em 1d10 + modificador de Destreza. Se reduzir a 0: projétil agarrado.', ARRAY['luvas']::text[], NULL, '1d10', ARRAY[]::text[], NULL, 'Incomum', 'Luvas que permitem agarrar projéteis voadores do ar.', '{"requer":true,"descricao":"Como reação quando atingido por projétil: reduz dano em 1d10 + modificador de Destreza. Se reduzir a 0: projétil agarrado"}', 'Itens de Uso e Ferramentas Magicas', ARRAY[]::text[], NULL, NULL),
  (231, 'Gauntlets of Ogre Power (Manoplas do Poder dos Ogros)', 'FOR do portador aumenta para 19 (se já for maior, não muda).', ARRAY['luvas', 'manoplas']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Forjadas com tendões de ogro. Aumentam a força brutal.', '{"requer":true,"descricao":"FOR do portador aumenta para 19 (se já for maior, não muda)"}', 'Itens de Uso e Ferramentas Magicas', ARRAY[]::text[], NULL, NULL),
  (232, 'Gloves of Swimming and Climbing (Luvas de Natação e Escalada)', 'Velocidade de escalada e natação igual à velocidade de terreno. Sem penalidades em testes de Atletismo para natação ou escalada.', ARRAY['luvas']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Luvas membranosas mágicas que melhoram ambas as capacidades físicas aquáticas e verticais.', '{"requer":true,"descricao":"Velocidade de escalada e natação igual à velocidade de terreno. Sem penalidades em testes de Atletismo para natação ou escalada"}', 'Itens de Uso e Ferramentas Magicas', ARRAY[]::text[], NULL, NULL),
  (233, 'Hat of Disguise (Chapéu do Disfarce)', 'Lança Disguise Self à vontade (incluindo parecer qualquer raça humanoide, tamanho similar). A ilusão inclui roupas mas não audição.', ARRAY['chapéu']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Chapéu favorito de espiões e ladinos. Lança Disguise Self à vontade.', '{"requer":true,"descricao":"Lança Disguise Self à vontade (incluindo parecer qualquer raça humanoide, tamanho similar). A ilusão inclui roupas mas não audição"}', 'Itens de Uso e Ferramentas Magicas', ARRAY['a_vontade']::text[], NULL, NULL),
  (234, 'Helm of Comprehending Languages (Elmo da Compreensão de Idiomas)', 'Lança Comprehend Languages à vontade enquanto vestindo. Entende qualquer idioma escrito ou falado.', ARRAY['elmo', 'capacete']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Capacete que concede compreensão universal de idiomas.', NULL, 'Itens de Uso e Ferramentas Magicas', ARRAY['a_vontade']::text[], NULL, NULL),
  (235, 'Helm of Telepathy (Elmo da Telepatia)', 'Detect Thoughts à vontade (CD 13 Sab). Pode enviar mensagens telepáticas para quem detectou.', ARRAY['elmo', 'capacete']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Capacete que abre comunicação mental bidirecional.', '{"requer":true,"descricao":"Detect Thoughts à vontade (CD 13 Sab). Pode enviar mensagens telepáticas para quem detectou"}', 'Itens de Uso e Ferramentas Magicas', ARRAY['a_vontade']::text[], NULL, NULL),
  (236, 'Helm of Brilliance (Elmo do Brilho)', '10 diamantes: Prismatic Spray. 20 rubins: Wall of Fire (3d6 fogo 10ft). 30 granadas de fogo: Fireball (5d6). 40 opais: Daylight. Gemas esgotam ao usar. CA +1 enquanto com gemas.', ARRAY['elmo', 'capacete']::text[], '{"ca":1}', '3d6', ARRAY['fogo']::text[], NULL, 'Muito Raro', 'Capacete repleto de gemas preciosas encantadas. Cada gema tem um poder.', '{"requer":true,"descricao":"10 diamantes: Prismatic Spray. 20 rubins: Wall of Fire (3d6 fogo 10ft)"}', 'Itens de Uso e Ferramentas Magicas', ARRAY['bonus_ca', 'luminoso']::text[], NULL, NULL),
  (237, 'Ioun Stone (Pedra de Ioun — várias)', 'Tipos: Absorção (absorve magias de 1° nível), Agilidade (+2 DEX), Conscientização (+2 Percepção passiva), Força (+2 STR), Força da Reserva (+5 slots de magia), Sustentação (sem comida/bebida), etc.', ARRAY['pedra flutuante']::text[], NULL, NULL, ARRAY['forca']::text[], NULL, 'Variável', 'Pedras que orbitam em torno da cabeça do portador concedendo diferentes bônus. Existem dezenas de tipos.', '{"requer":true,"descricao":"Tipos: Absorção (absorve magias de 1° nível), Agilidade (+2 DEX), Conscientização (+2 Percepção passiva), Força (+2 STR), Força da Reserva (+5 slots de magia), Sustentação (sem comida/bebida), etc"}', 'Itens de Uso e Ferramentas Magicas', ARRAY[]::text[], NULL, NULL),
  (238, 'Figurine of Wondrous Power (Estatueta do Poder Maravilhoso)', 'Cavalo Ébano: cavalo de guerra por 24h (1/semana). Mosca Âmbar: inseto gigante por 12h. Cão de Prata: por 6h (2/semana). Cabras de Onyx: 3 tipos, vários poderes.', ARRAY['estatueta']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Variável', 'Estatuetas de animais que ganham vida ao comando. Tipos: cavalo ébano, mosca âmbar, cabra de ouro, etc.', NULL, 'Itens de Uso e Ferramentas Magicas', ARRAY[]::text[], NULL, NULL),
  (239, 'Instrument of the Bards (Instrumento dos Bardos)', 'Vantagem em Persuasão. Magias de charme têm desvantagem para resistir. Concede magias específicas por instrumento (Canith Mandolin, Doss Lute, Fochlucan Bandore, etc.).', ARRAY['instrumento musical']::text[], NULL, NULL, ARRAY[]::text[], '{"classe":["bardo"]}', 'Raro a Lendário', 'Instrumentos encantados por colégios específicos de bardos. Potencializam magia bárdica.', '{"requer":true,"restricao_tipo":"classe","restricao":["bardo"],"descricao":"Vantagem em Persuasão. Magias de charme têm desvantagem para resistir"}', 'Itens de Uso e Ferramentas Magicas', ARRAY['vantagem', 'desvantagem']::text[], NULL, NULL),
  (240, 'Lyre of Building (Lira da Construção)', 'Tocar por 30 min: constrói edificação de pedra de 100ft³ (sem esforço físico). 1/dia: Reparo em objetos (Mending) instantâneo. Vantagem em Persuasão ao tocar para construtores.', ARRAY['instrumento musical']::text[], NULL, NULL, ARRAY[]::text[], '{"classe":["bardo"]}', 'Raro', 'Fantasia. Instrumento mágico que literalmente constrói edificações ao ser tocado. Inspirada na lenda de Orfeu e na lira de Anfião.', '{"requer":true,"restricao_tipo":"classe","restricao":["bardo"],"descricao":"Tocar por 30 min: constrói edificação de pedra de 100ft³ (sem esforço físico). 1/dia: Reparo em objetos (Mending) instantâneo"}', 'Itens de Uso e Ferramentas Magicas', ARRAY['usos_diarios', 'vantagem']::text[], NULL, 1),
  (241, 'Sending Stones (Pedras do Envio)', '1/dia por pedra: envia mensagem de 25 palavras à outra pedra instantaneamente (qualquer distância, mesmo outros planos).', ARRAY['par de pedras']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Par de pedras que permite comunicação instantânea à distância. A comunicação mais confiável entre aventureiros.', NULL, 'Itens de Uso e Ferramentas Magicas', ARRAY['usos_diarios']::text[], NULL, 1),
  (242, 'Spell Scroll (Pergaminho de Magia)', 'Contém uma magia. Conjurador do nível certo: usa automaticamente. Abaixo: CD 10 + nível da magia (INT) ou magia falhará. Queima após o uso.', ARRAY['pergaminho']::text[], NULL, NULL, ARRAY[]::text[], '{"classe":["conjurador"]}', 'Varia por nível', 'Pergaminhos com magias inscritas. Qualquer um pode tentar usar, mas falhas são possíveis para níveis acima do do usuário.', NULL, 'Itens de Uso e Ferramentas Magicas', ARRAY[]::text[], NULL, NULL),
  (243, 'Tome of Clear Thought (Tomo do Pensamento Claro)', 'Lendo por 48 horas (6 dias): INT +2 (máximo +2 acima do máximo normal). O livro perde poder por 100 anos após o uso.', ARRAY['livro mágico']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Muito Raro', 'Livro que ao ser lido aumenta permanentemente a Inteligência do leitor.', NULL, 'Itens de Uso e Ferramentas Magicas', ARRAY[]::text[], NULL, NULL),
  (244, 'Tome of Leadership and Influence (Tomo da Liderança)', '48 horas de leitura: CAR +2. Livro perde poder por 100 anos.', ARRAY['livro mágico']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Muito Raro', 'Tomo que aumenta o carisma de forma permanente.', NULL, 'Itens de Uso e Ferramentas Magicas', ARRAY[]::text[], NULL, NULL),
  (245, 'Tome of Understanding (Tomo da Compreensão)', '48 horas de leitura: SAB +2. Livro perde poder por 100 anos.', ARRAY['livro mágico']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Muito Raro', 'Tomo que aumenta permanentemente a Sabedoria.', NULL, 'Itens de Uso e Ferramentas Magicas', ARRAY[]::text[], NULL, NULL),
  (246, 'Hand of Vhaelor (Mão de Vhaelor)', 'FOR 20. Imune a dano de frio e relâmpago. 1/dia: Dominate Monster, Finger of Death, Plane Shift. Portador corrompe alinhamento para NE ao longo do tempo. Vhaelor sabe o que a mão vê.', ARRAY['corporal']::text[], NULL, NULL, ARRAY['gelo', 'relampago']::text[], '{"stats":{"FOR":20}}', 'Artefato', 'A mão mumificada do arquilich Vhaelor, Senhor dos Segredos. Para usar: amputar a própria mão e fixar a mão de Vhaelor no coto (processo doloroso e permanente).', '{"requer":true,"descricao":"Imune a dano de frio e relâmpago. 1/dia: Dominate Monster, Finger of Death, Plane Shift"}', 'Artefatos Lendarios', ARRAY['usos_diarios', 'imunidade', 'teleporte']::text[], NULL, 1),
  (247, 'Eye of Vhaelor (Olho de Vhaelor)', 'True Sight 120ft. X-Ray Vision. 1/dia: Clairvoyance, Crown of Madness, Disintegrate, Dominate Monster, Eyebite. Igual à mão: corrupto e vigilado por Vhaelor.', ARRAY['corporal']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Artefato', 'O olho arrancado de Vhaelor. Para usar: arrancar o próprio olho e colocar o olho de Vhaelor na cavidade.', '{"requer":true,"descricao":"True Sight 120ft. X-Ray Vision"}', 'Artefatos Lendarios', ARRAY['usos_diarios']::text[], NULL, 1),
  (248, 'Book of Vile Darkness (Livro da Escuridão Vil)', 'CAR +2 (máx 30). Portador não pode ser detectado como mal. Aprende ritual de Magia da Escuridão (10h leitura). Corrompe alinhamento para NE. Vantagem em ataques e dano contra criaturas boas.', ARRAY['livro']::text[], NULL, NULL, ARRAY[]::text[], '{"alinhamento":["maligno"]}', 'Artefato', 'O grimório mais maligno do multiverso. Compilado por uma entidade de maldade primordial durante séculos.', '{"requer":true,"restricao_tipo":"alinhamento","restricao":["maligno"],"descricao":"CAR +2 (máx 30). Portador não pode ser detectado como mal"}', 'Artefatos Lendarios', ARRAY['vantagem']::text[], NULL, NULL),
  (249, 'Book of Exalted Deeds (Livro das Boas Ações)', 'SAB +2 (máx 30). Portador emana aura de santidade. Vantagem em salvaguardas contra magias de criaturas malignas. Criaturas malignas têm desvantagem vs portador. Arma = +1d8 radiante.', ARRAY['livro']::text[], NULL, '1d8', ARRAY['radiante']::text[], '{"alinhamento":["bom"]}', 'Artefato', 'Contraparte sagrada do Livro da Escuridão Vil. Contém os ensinamentos de santos, anjos e deuses do bem.', '{"requer":true,"restricao_tipo":"alinhamento","restricao":["bom","sagrado"],"descricao":"SAB +2 (máx 30). Portador emana aura de santidade"}', 'Artefatos Lendarios', ARRAY['vantagem', 'desvantagem', 'salvaguarda']::text[], NULL, NULL),
  (250, 'Deck of Many Things (Baralho das Muitas Coisas)', '22 cartas (versão completa) ou 13 (parcial). Cada carta tem efeito único: desde +2 atributo, tesouro e desejos até perda de nível, aprisionamento da alma, ataque de demônio ou morte instantânea.', ARRAY['baralho']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Lendário', 'O item mais temido de todo o multiverso. Cartas de destino que podem elevar ou destruir qualquer aventureiro.', NULL, 'Artefatos Lendarios', ARRAY[]::text[], NULL, NULL),
  (251, 'Sphere of Annihilation (Esfera da Aniquilação)', 'Qualquer matéria que toque é aniquilada — sem HP, sem salvaguarda, sem ressurreição (exceto True Resurrection ou Wish). Controlada por CD de INT vs CD 25. Disintegrate a afeta temporariamente.', ARRAY['esfera']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Lendário', 'Esfera negra de nada puro — um buraco em realidade. Destrói tudo que toca absolutamente.', NULL, 'Artefatos Lendarios', ARRAY['salvaguarda']::text[], NULL, NULL),
  (252, 'Apparatus of Kwalish (Aparato de Kwalish)', 'Baú metálico que se transforma em lagosta mecânica. CA 20, 200 HP. Opera com 10 alavancas. Pode andar no fundo do mar, agarrar inimigos (pinças: 2d10), resistência a pressão profunda. Hermeticamente fechado.', ARRAY['veículo mágico']::text[], '{"ca_base":20}', '2d10', ARRAY[]::text[], NULL, 'Lendário', 'Veículo submarino em forma de lagosta, criado pelo excêntrico inventor mágico Kwalish.', NULL, 'Artefatos Lendarios', ARRAY['resistencia', 'bonus_ca']::text[], NULL, NULL),
  (253, 'Artifact: Orb of the Void', 'Portador: visão verdadeira 120ft mas não pode sonhar. Lança Antimagia (Antimagic Field) 1/semana. 1/dia: Finger of Death, Power Word Kill. Ao longo de semanas: portador esquece memórias.', ARRAY['orbe']::text[], NULL, NULL, ARRAY[]::text[], '{"especial":"amaldicoado"}', 'Artefato', 'Fantasia cósmica original. Fragmento do Vazio Primordial anterior à criação. Quem o segura escuta o sussurro do nada.', NULL, 'Artefatos Lendarios', ARRAY['usos_diarios']::text[], NULL, 1),
  (254, 'Crown of the Eternal King', 'Portador: +4 CAR, +4 SAB. Todas as criaturas reconhecem a autoridade do portador (como Crown of Madness mas consensual). 1/dia: Dominate Monster. Portador não pode descansar sem governar um território.', ARRAY['coroa']::text[], '{"ca":4}', NULL, ARRAY[]::text[], NULL, 'Artefato', 'Fantasia épica. Forjada pelos deuses da ordem para o primeiro rei mortal do mundo. Dá ao portador o direito divino de governar — e a carga que vem com isso.', '{"requer":true,"restricao_tipo":"especial","restricao":["Portador deve ter território"],"descricao":"Portador: +4 CAR, +4 SAB. Todas as criaturas reconhecem a autoridade do portador (como Crown of Madness mas consensual)"}', 'Artefatos Lendarios', ARRAY['usos_diarios']::text[], NULL, 1),
  (255, 'Lute of Ages', 'Todas as magias de bardo são maximizadas. 1/dia: Wish (somente efeitos narrativos/históricos — não pode ser usado em combate). Pode alterar memórias de audiência (Modify Memory em massa, raio 300ft).', ARRAY['instrumento']::text[], NULL, NULL, ARRAY[]::text[], '{"classe":["bardo"]}', 'Artefato', 'Fantasia élfica. O instrumento tocado pelo primeiro bardo do mundo para criar a segunda lua. Agora cada nota muda a realidade levemente.', '{"requer":true,"restricao_tipo":"classe","restricao":["bardo"],"descricao":"Todas as magias de bardo são maximizadas. 1/dia: Wish (somente efeitos narrativos/históricos — não pode ser usado em combate)"}', 'Artefatos Lendarios', ARRAY['usos_diarios']::text[], NULL, 1),
  (256, 'Tablet of Fate', 'Portador vê os próximos 3 eventos do destino de cada criatura vista (DM descreve vagamente). 1/dia: reescreve o destino de uma criatura (como Geas + Modify Memory combinados, CD 25).', ARRAY['tábua']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Artefato', 'Mitologia mesopotâmica adaptada. A tábua que contém todos os destinos escritos. Quem lê pode alterar o que está escrito — mas o destino resiste.', '{"requer":true,"restricao_tipo":"especial","restricao":["Cada uso: portador envelhece 1d10 anos"],"descricao":"Portador vê os próximos 3 eventos do destino de cada criatura vista (DM descreve vagamente). 1/dia: reescreve o destino de uma criatura (como Geas + Modify Memory combinados, CD 25)"}', 'Artefatos Lendarios', ARRAY['usos_diarios']::text[], NULL, 1),
  (257, 'The Ring of Dominion (O Anel do Domínio)', 'Invisibilidade perpétua (portador se torna parcialmente etéreo). Portador sente presença de seres poderosos. +5 em Furtividade. Gradualmente corrói a alma: -1 CON/semana. Atrai servos do criador.', ARRAY['anel']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Artefato', 'Fantasia clássica. Forjado por Morthaul para dominar os outros anéis. ''Um anel para a todos governar, e na escuridão aprisioná-los.''', '{"requer":true,"restricao_tipo":"especial","restricao":["Cria dependência crescente"],"descricao":"Invisibilidade perpétua (portador se torna parcialmente etéreo). Portador sente presença de seres poderosos"}', 'Artefatos Lendarios', ARRAY['invisibilidade']::text[], NULL, NULL),
  (258, 'Starhearts', 'Emite luz sagrada (como Daylight mas radiante, 60ft). Mãos malignas sofrem 6d10 radiante ao tocar. 1/dia: Heal (cura máxima). Criaturas de escuridão não se aproximam voluntariamente.', ARRAY['joias', 'pedras preciosas']::text[], NULL, '6d10', ARRAY['radiante']::text[], NULL, 'Artefato', 'Fantasia élfica. Joias criadas com a luz das Duas Árvores do mundo. Irradiam luz pura e não podem ser seguradas por mãos maliciosas sem queimar.', NULL, 'Artefatos Lendarios', ARRAY['usos_diarios', 'cura', 'luminoso']::text[], NULL, 1),
  (259, 'Mirror of Life Trapping (Espelho da Vida Aprisionada)', 'Criatura em 30ft: CD 15 Carisma ou fica aprisionada em célula dimensional. 12 slots. Liberação por comando. Ao destruir: todas as almas voltam ao plano material.', ARRAY['espelho']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Muito Raro', 'Espelho com 12 câmaras extradimensionais. Qualquer criatura que se veja no reflexo pode ser aprisionada.', NULL, 'Artefatos Lendarios', ARRAY[]::text[], NULL, NULL),
  (260, 'Cubic Gate (Portão Cúbico)', '6 faces = 6 planos (Plano Material + 5 outros). Pressionar face 1x: abre portal de 1ft ao plano. 2x: transporta portador ao plano. Pode ser usado como arma de lançamento (3d6 dano de força).', ARRAY['cubo']::text[], NULL, '3d6', ARRAY['forca']::text[], NULL, 'Lendário', 'Cubo com cada face sintonizada a um plano diferente do multiverso.', '{"requer":true,"descricao":"6 faces = 6 planos (Plano Material + 5 outros). Pressionar face 1x: abre portal de 1ft ao plano"}', 'Artefatos Lendarios', ARRAY[]::text[], NULL, NULL),
  (261, 'Candle of Invocation (Vela da Invocação)', 'Dura 4 horas (não recarrega). Clérigos e druidas do alinhamento correto: Spell Slots de níveis extras. Regeneração de 1 nível/hora de meditação. 1/uso: Gate para o plano divino.', ARRAY['vela']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Muito Raro', 'Vela alinhada com um deus específico. Ao acender, cria zona sagrada.', '{"requer":true,"restricao_tipo":"especial","restricao":["divino"],"descricao":"Dura 4 horas (não recarrega). Clérigos e druidas do alinhamento correto: Spell Slots de níveis extras"}', 'Artefatos Lendarios', ARRAY[]::text[], NULL, NULL),
  (262, 'Olde Bell of Warning', 'Toca quando criatura maligna se aproxima de 300ft. Som audível apenas por aliados. 1/dia: Alarm em área de 100ft (dura 8h). Criaturas malignas têm desvantagem para se aproximar silenciosamente.', ARRAY['sino']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Lendário', 'Fantasia clássica. Sino forjado por anjos para avisar da aproximação do mal. Toca sozinho quando criaturas de alinhamento maligno se aproximam.', NULL, 'Artefatos Lendarios', ARRAY['usos_diarios', 'vantagem', 'desvantagem']::text[], NULL, 1),
  (263, 'Flask of Eternal Flames', 'Chama não apaga com vento, água ou magia normal (somente Wish ou Dispel Magic nível 9). Lança Fireball 3/dia (CD 20, 12d6). 1/semana: Fire Storm (nível 7). Portador imune a fogo.', ARRAY['frasco']::text[], NULL, '12d6', ARRAY['fogo']::text[], NULL, 'Artefato', 'Fantasia elemental. Frasco que contém uma chama aprisionada do Plano Elemental do Fogo — não pode ser apagada por meios normais.', '{"requer":true,"descricao":"Chama não apaga com vento, água ou magia normal (somente Wish ou Dispel Magic nível 9). Lança Fireball 3/dia (CD 20, 12d6)"}', 'Artefatos Lendarios', ARRAY['usos_diarios', 'imunidade']::text[], NULL, 3),
  (264, 'Caduceus', 'Portador pode viajar entre planos à vontade (Plane Shift, 3/dia). Lança Fly à vontade. Todos os mercadores reconhecem como mensageiro sagrado (proteção diplomática automática). Cura doenças ao tocar.', ARRAY['bastão alado']::text[], NULL, NULL, ARRAY[]::text[], '{"especial":"divino"}', 'Artefato', 'Mitologia grega / fantasia clássica. Bastão de Hermes/Mercúrio com duas serpentes entrelaçadas e asas. Símbolo de comunicação, comércio e viagem.', NULL, 'Artefatos Lendarios', ARRAY['usos_diarios', 'a_vontade', 'cura', 'voo', 'teleporte']::text[], NULL, 3),
  (265, 'Cloak of Elvenkind (Manto Élfico)', 'Vantagem em testes de Furtividade. Percepção passiva de observadores para detectar o portador tem desvantagem.', ARRAY['manto']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Tecido por artesãos élficos com fios de névoa e luz da lua. A cor se adapta perfeitamente ao ambiente.', '{"requer":true,"descricao":"Vantagem em testes de Furtividade. Percepção passiva de observadores para detectar o portador tem desvantagem"}', 'Miscelanea Magica', ARRAY['vantagem', 'desvantagem']::text[], NULL, NULL),
  (266, 'Cloak of Displacement (Manto do Deslocamento)', 'Atacantes têm desvantagem ao atacar o portador. O efeito desaparece após o primeiro hit mas retorna no início do próximo turno.', ARRAY['manto']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Manto que projeta ilusão de posição ligeiramente deslocada do portador.', '{"requer":true,"descricao":"Atacantes têm desvantagem ao atacar o portador. O efeito desaparece após o primeiro hit mas retorna no início do próximo turno"}', 'Miscelanea Magica', ARRAY['vantagem', 'desvantagem', 'retorno']::text[], NULL, NULL),
  (267, 'Belt of Giant Strength (Cinto da Força dos Gigantes)', 'Tipos: Hill (21 STR/Incomum), Stone/Frost (23 STR/Raro), Fire (25/Raro), Cloud (27/Muito Raro), Storm (29/Lendário).', ARRAY['cinto']::text[], NULL, NULL, ARRAY['fogo', 'gelo']::text[], NULL, 'Variável', 'Cintos forjados com materiais de gigantes. Tipos crescem em poder com o tipo de gigante.', '{"requer":true,"descricao":"Tipos: Hill (21 STR/Incomum), Stone/Frost (23 STR/Raro), Fire (25/Raro), Cloud (27/Muito Raro), Storm (29/Lendário)"}', 'Miscelanea Magica', ARRAY[]::text[], NULL, NULL),
  (268, 'Headband of Intellect (Tiara do Intelecto)', 'INT do portador aumenta para 19 (se já for maior, não muda).', ARRAY['tiara']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Tiara que aumenta inteligência para nível extraordinário.', '{"requer":true,"descricao":"INT do portador aumenta para 19 (se já for maior, não muda)"}', 'Miscelanea Magica', ARRAY[]::text[], NULL, NULL),
  (269, 'Periapt of Wisdom (Periapt da Sabedoria)', 'SAB do portador aumenta para 19 (se já for maior, não muda).', ARRAY['amuleto']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Amuleto que concentra e amplifica a sabedoria do portador.', '{"requer":true,"descricao":"SAB do portador aumenta para 19 (se já for maior, não muda)"}', 'Miscelanea Magica', ARRAY[]::text[], NULL, NULL),
  (270, 'Circlet of Blasting (Tiara do Estilhaço)', '1/dia: Scorching Ray (3 raios de 2d6 fogo cada, +5 em ataque) ao entardecer. Recarrega ao amanhecer.', ARRAY['tiara']::text[], '{"ataque":5,"dano":5}', '2d6', ARRAY['fogo']::text[], NULL, 'Incomum', 'Tiara que permite lançar raio solar.', NULL, 'Miscelanea Magica', ARRAY['usos_diarios']::text[], NULL, 1),
  (271, 'Diadem of the Thinker', '+4 INT. Vantagem em todos os testes de INT. 1/dia: Legend Lore (como magia nível 5).', ARRAY['diadema']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Fantasia clássica. Diadema de platina que amplifica faculdades mentais.', '{"requer":true,"descricao":"Vantagem em todos os testes de INT. 1/dia: Legend Lore (como magia nível 5)"}', 'Miscelanea Magica', ARRAY['usos_diarios', 'vantagem']::text[], NULL, 1),
  (272, 'Bracers of Archery (Braçadeiras de Arco)', '+2 em dano com arcos (longo e curto). Proficiência em arcos enquanto vestindo.', ARRAY['braçadeiras']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Braçadeiras que guiam o braço do arqueiro para disparos perfeitos.', '{"requer":true,"descricao":"+2 em dano com arcos (longo e curto). Proficiência em arcos enquanto vestindo"}', 'Miscelanea Magica', ARRAY[]::text[], NULL, NULL),
  (273, 'Bracers of Defense (Braçadeiras de Defesa)', '+2 CA enquanto sem armadura e sem escudo.', ARRAY['braçadeiras']::text[], '{"ca":2}', NULL, ARRAY[]::text[], NULL, 'Raro', 'Braçadeiras para monges e feiticeiros — conjuradores que não podem usar armadura.', '{"requer":true,"descricao":"+2 CA enquanto sem armadura e sem escudo"}', 'Miscelanea Magica', ARRAY['bonus_ca']::text[], NULL, NULL),
  (274, 'Mantle of Spell Resistance (Manto de Resistência Mágica)', 'Vantagem em salvaguardas contra magias.', ARRAY['manto']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Manto que cria campo mágico resistente a magia.', '{"requer":true,"descricao":"Vantagem em salvaguardas contra magias"}', 'Miscelanea Magica', ARRAY['vantagem', 'salvaguarda']::text[], NULL, NULL),
  (275, 'Wings of Flying (Asas do Voo)', 'Ação: asas brotam nas costas (velocidade de voo 60ft) por 4 horas. Após uso: 2d12 horas para recarregar.', ARRAY['asas', 'manto']::text[], NULL, '2d12', ARRAY[]::text[], NULL, 'Muito Raro', 'Manto que se transforma em asas. O item ideal para quem quer voar permanentemente.', '{"requer":true,"descricao":"Ação: asas brotam nas costas (velocidade de voo 60ft) por 4 horas. Após uso: 2d12 horas para recarregar"}', 'Miscelanea Magica', ARRAY['voo']::text[], NULL, NULL),
  (276, 'Horseshoes of Speed (Ferraduras da Velocidade)', 'A montaria: velocidade aumentada em +30ft.', ARRAY['ferraduras']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Ferraduras para montar. Aceleram enormemente a montaria.', NULL, 'Miscelanea Magica', ARRAY[]::text[], NULL, NULL),
  (277, 'Horseshoes of a Zephyr (Ferraduras do Zéfiro)', 'Montaria flutua 4 polegadas acima de qualquer superfície. Pode galgar sobre água, areia movediça, lama, etc. Não deixa rastros.', ARRAY['ferraduras']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Muito Raro', 'Ferraduras que permitem à montaria cavalgar sobre qualquer superfície — incluindo ar.', NULL, 'Miscelanea Magica', ARRAY[]::text[], NULL, NULL),
  (278, 'Cloak of the Bat (Manto do Morcego)', 'Vantagem em Furtividade em áreas escuras. 1/dia: transforma-se em morcego real (como Polymorph) por 1 hora. Voar (suspendendo pelo teto com o manto): velocidade de voo 40ft.', ARRAY['manto']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Manto negro como a noite que concede capacidades dos morcegos.', '{"requer":true,"descricao":"Vantagem em Furtividade em áreas escuras. 1/dia: transforma-se em morcego real (como Polymorph) por 1 hora"}', 'Miscelanea Magica', ARRAY['usos_diarios', 'vantagem', 'cura', 'voo']::text[], NULL, 1),
  (279, 'Folding Boat (Barco Dobrável)', 'Palavra 1: Barco de remo para 4 pessoas (10x4ft). Palavra 2: Veleiro para 15 pessoas. Palavra 3: Volta a ser caixinha. Inclui equipamento náutico.', ARRAY['caixa', 'barco']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Caixinha que se transforma em barco ao comando. Genialidade arcana portátil.', NULL, 'Miscelanea Magica', ARRAY[]::text[], NULL, NULL),
  (280, 'Wind Fan (Leque do Vento)', '1/dia: Gust of Wind (linha de vento 60ft x 10ft, CD 13 STR ou empurra 15ft). Uso adicional: 20% chance de quebrar permanentemente.', ARRAY['leque']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Leque que cria ventania ao ser agitado.', NULL, 'Miscelanea Magica', ARRAY['usos_diarios']::text[], NULL, 1),
  (281, 'Lantern of Revealing (Lanterna da Revelação)', 'Em 30ft: invisibilidade é suprimida (criaturas ficam visíveis mesmo sob efeito). Não remove invisibilidade mas a neutraliza na área iluminada.', ARRAY['lanterna']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Lanterna que ilumina o invisível e o oculto.', NULL, 'Miscelanea Magica', ARRAY['invisibilidade', 'luminoso']::text[], NULL, NULL),
  (282, 'Driftglobe (Globo Flutuante)', 'Comando: flutua até 5ft do portador e ilumina (Light ou Daylight). Segue o portador automaticamente.', ARRAY['globo']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Globo de vidro que flutua e ilumina à vontade.', NULL, 'Miscelanea Magica', ARRAY['luminoso']::text[], NULL, NULL),
  (283, 'Stone of Good Luck (Pedra da Sorte / Luckstone)', '+1 em todos os testes de habilidade e salvaguardas.', ARRAY['pedra', 'amuleto']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Pedra polida de boa sorte. Usada por jogadores, aventureiros e qualquer pessoa que precise de vantagem.', '{"requer":true,"descricao":"+1 em todos os testes de habilidade e salvaguardas"}', 'Miscelanea Magica', ARRAY['salvaguarda']::text[], NULL, NULL),
  (284, 'Pipes of Haunting (Gaitas dos Assombros)', '3/dia: toca música assombrosa. Criaturas em 30ft: CD 15 Sab ou ficam assustadas por 1 minuto (fogem do portador). Humanoides afetados.', ARRAY['instrumento de sopro']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Gaitas que tocam uma música perturbante que aterroriza os ouvintes.', '{"requer":true,"descricao":"3/dia: toca música assombrosa. Criaturas em 30ft: CD 15 Sab ou ficam assustadas por 1 minuto (fogem do portador)"}', 'Miscelanea Magica', ARRAY['usos_diarios']::text[], NULL, 3),
  (285, 'Pipes of the Sewers (Gaitas dos Esgotos)', '3/dia: convoca 1d4+4 enxames de ratos (aparecem em 1d4 rodadas). Portador controla os ratos enquanto toca (requer concentração).', ARRAY['instrumento de sopro']::text[], '{"ca_base":1}', '1d4+4', ARRAY[]::text[], NULL, 'Incomum', 'Gaitas que convocam ratos em massa. Mais útil do que parece.', '{"requer":true,"descricao":"3/dia: convoca 1d4+4 enxames de ratos (aparecem em 1d4 rodadas). Portador controla os ratos enquanto toca (requer concentração)"}', 'Miscelanea Magica', ARRAY['usos_diarios', 'invocacao', 'concentracao']::text[], NULL, 3),
  (286, 'Horn of Blasting (Trompa do Estilhaço)', '1/dia: cone sônico (30ft, 5d6 trovão, CD 15 Con ou atordoado). Vidro na área quebra automaticamente. 20% chance de ser destruída ao usar.', ARRAY['trompa']::text[], NULL, '5d6', ARRAY['trovao']::text[], NULL, 'Raro', 'Trompa que cria explosão sônica devastadora.', NULL, 'Miscelanea Magica', ARRAY['usos_diarios']::text[], NULL, 1),
  (287, 'Horn of Valhalla (Trompa de Valhalla)', 'Prata (Raro): 2d4+2 berserkers. Bronze (Muito Raro): 3d4+3. Latão: 4d4+4 guerreiros (Lendário). Guerreiros servem por 1 hora e somem. 7 dias entre usos.', ARRAY['trompa']::text[], NULL, '2d4+2', ARRAY[]::text[], NULL, 'Raro a Lendário', 'Trompa nórdica que convoca guerreiros berserkers do Valhalla para lutar pelo portador.', NULL, 'Miscelanea Magica', ARRAY[]::text[], NULL, NULL),
  (288, 'Chime of Opening (Sino da Abertura)', '10 usos. Abre qualquer porta, tampa, fechadura ou recipiente trancado em 120ft (não mágico). Ao esgotar: fica mundano.', ARRAY['sino pequeno']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Sino que abre qualquer fechadura não mágica ao ser tocado.', NULL, 'Miscelanea Magica', ARRAY[]::text[], NULL, NULL),
  (289, 'Manual of Bodily Health', '48h leitura: CON +2 (acima do máximo). Perde poder por 100 anos.', ARRAY['livro mágico']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Muito Raro', 'Livro que aumenta permanentemente a Constituição do leitor.', NULL, 'Miscelanea Magica', ARRAY[]::text[], NULL, NULL),
  (290, 'Manual of Gainful Exercise', '48h leitura: STR +2. Perde poder por 100 anos.', ARRAY['livro mágico']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Muito Raro', 'Manual de exercícios encantado que aumenta permanentemente a Força.', NULL, 'Miscelanea Magica', ARRAY[]::text[], NULL, NULL),
  (291, 'Manual of Quickness of Action', '48h leitura: DEX +2. Perde poder por 100 anos.', ARRAY['livro mágico']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Muito Raro', 'Manual que aumenta permanentemente a Destreza.', NULL, 'Miscelanea Magica', ARRAY[]::text[], NULL, NULL),
  (292, 'Well of Many Worlds', 'Abre portal de 6ft em qualquer local (DM determina destino — pode ser específico ou aleatório). Portal bidirecional por 1 minuto. Dobrar: fecha portal.', ARRAY['pano negro']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Lendário', 'Pano de seda negro que quando aberto no chão cria portal bidirecional para outro plano.', NULL, 'Miscelanea Magica', ARRAY[]::text[], NULL, NULL),
  (293, 'Arrow-Catching Shield (Escudo Pega-Flechas)', '+2 CA contra ataques com projéteis. Como reação: interceptar projéteis destinados a aliados em 5ft (redirecionar ao portador, com bônus de CA).', ARRAY['escudo']::text[], '{"ca":2}', NULL, ARRAY[]::text[], NULL, 'Raro', 'Escudo que magneticamente atrai e para projéteis.', '{"requer":true,"descricao":"+2 CA contra ataques com projéteis. Como reação: interceptar projéteis destinados a aliados em 5ft (redirecionar ao portador, com bônus de CA)"}', 'Miscelanea Magica', ARRAY['bonus_ca']::text[], NULL, NULL),
  (294, 'Dimensional Shackles (Algemas Dimensionais)', 'Criatura algemada: não pode usar teleportação, Plane Shift, Ethereal Jaunt ou qualquer método de viagem dimensional. Requer CD 30 STR para quebrar.', ARRAY['algemas']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Algemas que impedem completamente viagem dimensional e teleportação.', NULL, 'Miscelanea Magica', ARRAY['teleporte']::text[], NULL, NULL),
  (295, 'Mask of Many Faces (Máscara das Muitas Faces)', 'Lança Disguise Self à vontade enquanto vestida. Pode replicar rostos específicos vistos antes (SAB CD 15 para perceber a ilusão). Não altera voz.', ARRAY['máscara']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Incomum', 'Fantasia. Máscara mágica que altera a aparência do portador. Favorita de espiões, atores e ladrões.', '{"requer":true,"descricao":"Lança Disguise Self à vontade enquanto vestida. Pode replicar rostos específicos vistos antes (SAB CD 15 para perceber a ilusão)"}', 'Miscelanea Magica', ARRAY['a_vontade']::text[], NULL, NULL),
  (296, 'Gauntlet of Spell Storing (Manopla do Armazenamento)', 'Armazena 1 magia de até nível 5. Ao acertar ataque corpo a corpo: descarrega a magia no alvo. Magia usa a CD e ataque do conjurador original.', ARRAY['manopla']::text[], NULL, NULL, ARRAY[]::text[], NULL, 'Raro', 'Fantasia arcana. Manopla que pode armazenar uma magia e ser ativada no momento do golpe.', '{"requer":true,"descricao":"Armazena 1 magia de até nível 5. Ao acertar ataque corpo a corpo: descarrega a magia no alvo"}', 'Miscelanea Magica', ARRAY[]::text[], NULL, NULL),
  (297, 'Tome of the Stilled Tongue (Tomo da Língua Imóvel)', '+2 INT (máx 30). +2 em CD de magias. 1/dia cada: Finger of Death, Mislead, Animate Dead (5 mortos-vivos). Vhaelor lê todos os pensamentos do portador enquanto usa o livro.', ARRAY['livro']::text[], NULL, NULL, ARRAY[]::text[], '{"classe":["mago"]}', 'Artefato', 'Grimório de Vhaelor — cada volume contém línguas mumificadas de seus segredos preferidos. Estudar o tomo é perigoso e viciante.', '{"requer":true,"restricao_tipo":"classe","restricao":["mago","bruxo"],"descricao":"+2 INT (máx 30). +2 em CD de magias"}', 'Miscelanea Magica', ARRAY['usos_diarios']::text[], NULL, 1),
  (298, 'Ring of Shooting Stars — Nível Máximo', 'Cargas ilimitadas de Shooting Stars. Portador pode voar (velocidade 60ft). 1/dia: Meteor Swarm (como magia de 9° nível). À noite: lança luz de 100ft.', ARRAY['variante artefato']::text[], NULL, NULL, ARRAY['radiante']::text[], NULL, 'Artefato (versão única)', 'Fantasia astral. A versão única do anel, criada durante um alinhamento estelar de milênio em milênio. Contém infinitas estrelas.', '{"requer":true,"restricao_tipo":"especial","restricao":["Coroa de estrelas visível sobre a cabeça do portador"],"descricao":"Cargas ilimitadas de Shooting Stars. Portador pode voar (velocidade 60ft)"}', 'Miscelanea Magica', ARRAY['usos_diarios', 'voo', 'luminoso']::text[], NULL, 1),
  (299, 'Sword of the Sunlord', '+3 em ataque/dano. Dano extra 3d8 radiante. Portador: imune a escuridão mágica. 1/dia: Sunbeam (nível 6, 6d8 radiante por raio). Criatura morta-viva que olhar para a espada: CD 19 Con ou cega.', ARRAY['espada longa']::text[], '{"ataque":3,"dano":3}', '3d8', ARRAY['radiante']::text[], '{"alinhamento":["bom"]}', 'Lendário', 'Fantasia de campanha original. Forjada pelo deus do sol para seu campeão mortal. Brilha como um sol em miniatura.', '{"requer":true,"restricao_tipo":"alinhamento","restricao":["bom","sagrado"],"descricao":"+3 em ataque/dano. Dano extra 3d8 radiante"}', 'Miscelanea Magica', ARRAY['usos_diarios', 'imunidade']::text[], NULL, 1),
  (300, 'Serpent Scale Armor', 'CA 14 + Des (máx 2). Resistência a veneno. Imune à condição envenenado. Vantagem em Furtividade (escamas silenciosas). 1/dia: Poison Spray (nível 3, 6d12).', ARRAY['escamas de cobra']::text[], '{"ca_base":14}', '6d12', ARRAY['veneno']::text[], NULL, 'Raro', 'Fantasia tropical. Armadura feita de escamas de serpentes encantadas pelos Naghari. Flexível, silenciosa e resistente a veneno.', '{"requer":true,"descricao":"CA 14 + Des (máx 2). Resistência a veneno"}', 'Miscelanea Magica', ARRAY['usos_diarios', 'imunidade', 'vantagem', 'resistencia', 'bonus_ca']::text[], NULL, 1),
  (301, 'Gladiator''s Net of the Arena', '+1 em ataque de arremesso. Prender: CD 17 STR ou DEX para escapar. Alvo preso: desavantagem em ataques e imóvel. Cada 10ft percorridos: 1d6 dano cortante pelos arames.', ARRAY['rede gladiatorial']::text[], '{"ataque":1,"dano":1}', '1d6', ARRAY[]::text[], NULL, 'Raro', 'Fantasia greco-romana. Rede tecida por artesãos das arenas sagradas de uma cidade-estado de guerreiros. Cada nó contém um feitiço menor.', NULL, 'Miscelanea Magica', ARRAY['vantagem', 'arremessavel']::text[], NULL, NULL),
  (302, 'Circlet of Human Perfection', 'Portador humano: todos os atributos físicos e mentais tratados como 20 (se menores). Destreza mínima 20, Força mínima 20, etc. Portadores não-humanos: apenas CAR aumenta para 20.', ARRAY['tiara']::text[], NULL, NULL, ARRAY['forca']::text[], '{"raca":["humano"]}', 'Muito Raro', 'Fantasia. Tiara que aprimora todos os atributos físicos e mentais de humanos ao limite da perfeição. Criada por um rei que queria a elite humana perfeita.', '{"requer":true,"restricao_tipo":"raca","restricao":["humano"],"descricao":"Portador humano: todos os atributos físicos e mentais tratados como 20 (se menores). Destreza mínima 20, Força mínima 20, etc"}', 'Miscelanea Magica', ARRAY[]::text[], NULL, NULL),
  (303, 'Boots of the Winterlands (Botas dos Planos Gelados)', 'Resistência a dano de frio. Pode andar sobre gelo e neve sem penalidades ou dificuldades. Não sofre efeitos de clima frio natural.', ARRAY['botas']::text[], NULL, NULL, ARRAY['gelo']::text[], NULL, 'Incomum', 'Botas criadas por exploradores do plano elemental do frio.', '{"requer":true,"descricao":"Resistência a dano de frio. Pode andar sobre gelo e neve sem penalidades ou dificuldades"}', 'Miscelanea Magica', ARRAY['resistencia']::text[], NULL, NULL),
  (304, 'Cape of the Sylvaris', 'Portador: vantagem em salvaguardas contra encantamento. 1/dia: Misty Step à vontade por 1 minuto. Em luz de lua: portador fica semi-translúcido (vantagem em Furtividade).', ARRAY['manto']::text[], NULL, NULL, ARRAY['radiante']::text[], NULL, 'Raro', 'Fantasia feérica. Tecido nas florestas encantadas do Sylvaris por ninfas e sátiros durante um festival de lua cheia.', '{"requer":true,"descricao":"Portador: vantagem em salvaguardas contra encantamento. 1/dia: Misty Step à vontade por 1 minuto"}', 'Miscelanea Magica', ARRAY['usos_diarios', 'a_vontade', 'vantagem', 'luminoso', 'salvaguarda']::text[], NULL, 1);
